INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X01','math',1,'u2',ARRAY['M1-2-u2-C1','M1-2-u2-C2']::text[],'세 수 가운데 두 수만 계산하고 끝낸다 — 3+2+4를 5로','세 수는 두 수씩 두 번 계산한다는 것을 손가락으로 짚어 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X02','math',1,'u2',ARRAY['M1-2-u2-C2']::text[],'뺄셈을 뒤에서부터 한다 — 9−3−2에서 3−2를 먼저','뺄셈은 반드시 앞에서부터. 앞 두 수에 동그라미 치고 시작하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X03','math',1,'u2',ARRAY['M1-2-u2-C1','M1-2-u2-C2']::text[],'중간 답을 잊고 처음 수부터 다시 센다','앞 두 수의 답을 식 위에 연필로 적어 두게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X04','math',1,'u2',ARRAY['M1-2-u2-C3','M1-2-u2-C6']::text[],'10이 되는 짝을 잘못 안다 — 7의 짝을 4로','십 배열판의 빈칸을 눈으로 세게 하기. 손가락 열 개로도 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X05','math',1,'u2',ARRAY['M1-2-u2-C3','M1-2-u2-C5']::text[],'십 배열판에서 채운 칸과 빈칸을 헷갈려 센다','묻는 것이 채운 칸인지 빈칸인지 발문에 밑줄 긋고 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X06','math',1,'u2',ARRAY['M1-2-u2-C4']::text[],'□ 자리를 보지 않고 보이는 수를 그대로 답으로 쓴다 — 4+□=10에 4','□가 어디 있는지 먼저 짚고, 무엇을 묻는지 말로 바꿔 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X07','math',1,'u2',ARRAY['M1-2-u2-C5']::text[],'10에서 빼기를 더하기로 바꿔 계산한다 — 10−3을 13으로','− 기호를 소리 내어 읽게 하기. 배열판에서 덜어 내 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X08','math',1,'u2',ARRAY['M1-2-u2-C6','M1-2-u2-C7']::text[],'10을 만들고 남은 수를 더하지 않는다 — 7+3+5를 10으로','10을 만든 뒤 남은 수에 동그라미를 쳐 두고 마지막에 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X09','math',1,'u2',ARRAY['M1-2-u2-C7']::text[],'뺄셈이 섞인 식에서도 순서를 바꿔 10을 만든다','10 만들기는 더하기끼리만. 식에 −가 있으면 앞에서부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X10','math',1,'u2',ARRAY['M1-2-u2-C4']::text[],'10이 되는 덧셈식을 한 가지(5+5)만 떠올린다','1+9부터 9+1까지 짝을 차례로 적어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u2-X11','math',1,'u2',ARRAY['M1-2-u2-C3','M1-2-u2-C4']::text[],'10을 넘겨 짝을 만든다 — 6과 5를 10이라고 함','십 배열판은 칸이 열 개뿐. 넘치면 짝이 아니라는 것을 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#1','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',1,'mc','auto','그림을 보세요. 병아리는 모두 몇 마리인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],true,'{"seq":1,"concept":"M1-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 병아리는 모두 몇 마리인가요?","asset":{"type":"group_row","groups":[{"item":"🐤","n":2},{"item":"🐤","n":3},{"item":"🐤","n":1}],"op":"+"},"options":[{"t":"6","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"4","mis":"M1-2-u2-X03"}],"explanation":["앞의 두 무리를 먼저 세요 — 2 + 3 = 5.","거기에 1마리를 더하면 6마리예요.","세 무리를 한꺼번에 보지 말고 두 무리씩 세요."],"variant_rule":{"groups":{"items":[["🐤","🐤","🐤"],["🍎","🍎","🍎"],["⚽","⚽","⚽"],["🍪","🍪","🍪"]],"n":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#2','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',1,'sa','auto','그림을 보고 모두 몇 개인지 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C1","difficulty":1,"kind":"sa","stem":"그림을 보고 모두 몇 개인지 숫자로 쓰세요.","asset":{"type":"group_row","groups":[{"item":"🍎","n":3},{"item":"🍎","n":1},{"item":"🍎","n":3}],"op":"+"},"answer":["7"],"explanation":["앞의 두 무리를 먼저 더해요 — 3 + 1 = 4.","거기에 3개를 더하면 7개예요.","더한 수를 손가락으로 짚어 두면 잊지 않아요."],"variant_rule":{"groups":{"items":[["🐤","🐤","🐤"],["🍎","🍎","🍎"],["⚽","⚽","⚽"],["🍪","🍪","🍪"]],"n":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#3','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',1,'mc','auto','2 + 3 + 1 은 얼마인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],true,'{"seq":3,"concept":"M1-2-u2-C1","difficulty":1,"kind":"mc","stem":"2 + 3 + 1 은 얼마인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"7","mis":"M1-2-u2-X03"}],"explanation":["앞에서부터 계산해요 — 2 + 3 = 5.","5 + 1 = 6이에요.","5는 앞의 두 수만 더한 답이에요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#4','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',1,'sa','auto','4 + 2 + 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u2-C1","difficulty":1,"kind":"sa","stem":"4 + 2 + 3 은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["앞에서부터 계산해요 — 4 + 2 = 6.","6 + 3 = 9예요.","두 수씩 두 번 계산하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#5','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',2,'mc','auto','버스에 2명이 타고 있었어요. 정류장에서 3명이 타고, 다음 정류장에서 1명이 더 탔어요. 버스에 탄 사람은 모두 몇 명인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":5,"concept":"M1-2-u2-C1","difficulty":2,"kind":"mc","stem":"버스에 2명이 타고 있었어요. 정류장에서 3명이 타고, 다음 정류장에서 1명이 더 탔어요. 버스에 탄 사람은 모두 몇 명인가요?","options":[{"t":"6명","correct":true},{"t":"5명","mis":"M1-2-u2-X01"},{"t":"4명","mis":"M1-2-u2-X03"}],"explanation":["처음 2명에 3명을 더하면 5명이에요.","거기에 1명을 더하면 6명이에요.","탄 사람만 세면 되니까 모두 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#6','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',2,'sa','auto','1 + 5 + 2 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u2-C1","difficulty":2,"kind":"sa","stem":"1 + 5 + 2 는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["1 + 5 = 6이에요.","6 + 2 = 8이에요.","앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#7','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#8','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',2,'ox','auto','2 + 3 + 4 = 9 입니다.',ARRAY['M1-2-u2-X01']::text[],true,'{"seq":8,"concept":"M1-2-u2-C1","difficulty":2,"kind":"ox","stem":"2 + 3 + 4 = 9 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 계산하니까","correct":true},{"t":"세 수 가운데 두 수만 계산하면 되니까","mis":"M1-2-u2-X01"}],"explanation":["2 + 3 = 5예요.","5 + 4 = 9예요 — 맞아요.","세 수의 덧셈도 두 수씩 이어서 하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#9','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',2,'match','auto','식과 답을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u2-C1","difficulty":2,"kind":"match","stem":"식과 답을 알맞게 이어 보세요.","pairs":[{"l":"1 + 2 + 3","r":"6"},{"l":"2 + 2 + 4","r":"8"},{"l":"3 + 1 + 1","r":"5"}],"explanation":["앞의 두 수를 먼저 더해요.","1 + 2 = 3, 3 + 3 = 6이에요.","식마다 앞에서부터 차례로 계산해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_basic#10','math',1,2,'u2','L02','g1_2_math_u2_L02_basic','lesson_basic','M1-2-u2-C1',3,'error','auto','민수가 3 + 2 + 4 를 계산하고 "5!"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#1','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',2,'sa','auto','2 + 4 + 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C1","difficulty":2,"kind":"sa","stem":"2 + 4 + 3 은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["2 + 4 = 6이에요.","6 + 3 = 9예요.","앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#2','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',2,'mc','auto','주머니에 구슬이 3개 있어요. 지우가 2개를 넣고, 하늘이가 2개를 더 넣었어요. 주머니의 구슬은 모두 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":2,"concept":"M1-2-u2-C1","difficulty":2,"kind":"mc","stem":"주머니에 구슬이 3개 있어요. 지우가 2개를 넣고, 하늘이가 2개를 더 넣었어요. 주머니의 구슬은 모두 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"5개","mis":"M1-2-u2-X01"},{"t":"8개","mis":"M1-2-u2-X03"}],"explanation":["3 + 2 = 5개예요.","5 + 2 = 7개예요.","5는 하늘이가 넣기 전의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#3','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',3,'mc','auto','3 + 4 + 2 와 답이 같은 식은 무엇인가요?',ARRAY['M1-2-u2-X03','M1-2-u2-X01']::text[],false,'{"seq":3,"concept":"M1-2-u2-C1","difficulty":3,"kind":"mc","stem":"3 + 4 + 2 와 답이 같은 식은 무엇인가요?","options":[{"t":"2 + 4 + 3","correct":true},{"t":"3 + 4 + 3","mis":"M1-2-u2-X03"},{"t":"3 + 2","mis":"M1-2-u2-X01"}],"explanation":["3 + 4 + 2 = 9예요.","더하는 세 수가 같으면 순서를 바꿔도 답이 같아요 — 2 + 4 + 3 = 9예요.","수가 하나라도 달라지면 답도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#4','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',3,'sa','auto','빈칸에 알맞은 수를 숫자로 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#5','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',3,'error','auto','보라가 2 + 3 + 4 를 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#6','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',3,'ox','auto','1 + 3 + 4 = 8 입니다.',ARRAY['M1-2-u2-X01']::text[],true,'{"seq":6,"concept":"M1-2-u2-C1","difficulty":3,"kind":"ox","stem":"1 + 3 + 4 = 8 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 계산하니까","correct":true},{"t":"세 수 가운데 두 수만 계산하면 되니까","mis":"M1-2-u2-X01"}],"explanation":["1 + 3 = 4예요.","4 + 4 = 8이에요 — 맞아요.","두 수씩 이어서 계산하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#7','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',3,'mc','auto','접시에 딸기가 2개 있었어요. 언니가 3개를 놓고, 형이 2개를 놓았어요. 그런데 아직 하나도 먹지 않았어요. 접시의 딸기는 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":7,"concept":"M1-2-u2-C1","difficulty":3,"kind":"mc","stem":"접시에 딸기가 2개 있었어요. 언니가 3개를 놓고, 형이 2개를 놓았어요. 그런데 아직 하나도 먹지 않았어요. 접시의 딸기는 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"5개","mis":"M1-2-u2-X01"},{"t":"3개","mis":"M1-2-u2-X03"}],"explanation":["2 + 3 = 5개예요.","5 + 2 = 7개예요.","먹은 것이 없으니 빼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#8','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',4,'sa','auto','민수는 붙임 딱지를 어제 3장, 오늘 아침에 2장, 오늘 저녁에 4장 모았어요. 민수가 모은 붙임 딱지는 모두 몇 장인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C1","difficulty":4,"kind":"sa","stem":"민수는 붙임 딱지를 어제 3장, 오늘 아침에 2장, 오늘 저녁에 4장 모았어요. 민수가 모은 붙임 딱지는 모두 몇 장인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["3 + 2 = 5장이에요.","5 + 4 = 9장이에요.","세 번 모았으니 세 수를 모두 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#9','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',4,'mc','auto','1, 3, 4 세 수를 모두 한 번씩 써서 더했어요. 가장 큰 답은 얼마인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":9,"concept":"M1-2-u2-C1","difficulty":4,"kind":"mc","stem":"1, 3, 4 세 수를 모두 한 번씩 써서 더했어요. 가장 큰 답은 얼마인가요?","options":[{"t":"8","correct":true},{"t":"4","mis":"M1-2-u2-X01"},{"t":"9","mis":"M1-2-u2-X03"}],"explanation":["세 수를 모두 더하면 1 + 3 + 4 = 8이에요.","순서를 어떻게 바꿔도 답은 8로 같아요.","더하기는 순서를 바꿔도 답이 변하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L02_challenge#10','math',1,2,'u2','L02','g1_2_math_u2_L02_challenge','lesson_challenge','M1-2-u2-C1',4,'essay','teacher','세 수를 더할 때 왜 두 수씩 차례로 계산해야 하는지, 4 + 2 + 3 을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C1","difficulty":4,"kind":"essay","stem":"세 수를 더할 때 왜 두 수씩 차례로 계산해야 하는지, 4 + 2 + 3 을 예로 들어 설명해 보세요.","answer_guide":"「4 + 2 = 6을 먼저 구하고, 그 6에 3을 더해 9」처럼 앞의 답을 다음 계산에 이어 쓴다는 점을 말하면 통과.","explanation":["4 + 2 = 6을 먼저 구해요.","그 6에 3을 더해 9가 돼요.","한꺼번에 세면 하나를 빠뜨리기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#1','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',1,'mc','auto','8 − 3 − 2 는 얼마인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X02']::text[],true,'{"seq":1,"concept":"M1-2-u2-C2","difficulty":1,"kind":"mc","stem":"8 − 3 − 2 는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"7","mis":"M1-2-u2-X02"}],"explanation":["앞에서부터 계산해요 — 8 − 3 = 5.","5 − 2 = 3이에요.","5는 앞의 두 수만 계산한 답이에요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#2','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',1,'sa','auto','9 − 2 − 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C2","difficulty":1,"kind":"sa","stem":"9 − 2 − 4 는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9 − 2 = 7이에요.","7 − 4 = 3이에요.","뺄셈도 앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#3','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',1,'mc','auto','그림에서 앞에서부터 차례로 덜어 내면 몇 개가 남나요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":3,"concept":"M1-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림에서 앞에서부터 차례로 덜어 내면 몇 개가 남나요?","asset":{"type":"group_row","groups":[{"item":"🍪","n":7},{"item":"🍪","n":3},{"item":"🍪","n":2}],"op":"-"},"options":[{"t":"2","correct":true},{"t":"4","mis":"M1-2-u2-X01"},{"t":"6","mis":"M1-2-u2-X03"}],"explanation":["처음 7개에서 3개를 덜면 4개예요.","4개에서 2개를 더 덜면 2개가 남아요.","4는 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#4','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',1,'sa','auto','7 − 1 − 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u2-C2","difficulty":1,"kind":"sa","stem":"7 − 1 − 3 은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["7 − 1 = 6이에요.","6 − 3 = 3이에요.","앞에서부터 하나씩 덜어 내요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#5','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',2,'mc','auto','사탕 9개가 있었어요. 지우가 3개를 먹고, 하늘이가 2개를 먹었어요. 남은 사탕은 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":5,"concept":"M1-2-u2-C2","difficulty":2,"kind":"mc","stem":"사탕 9개가 있었어요. 지우가 3개를 먹고, 하늘이가 2개를 먹었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M1-2-u2-X01"},{"t":"5개","mis":"M1-2-u2-X03"}],"explanation":["9 − 3 = 6개예요.","6 − 2 = 4개예요.","6은 지우가 먹은 뒤의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
