INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#7','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#8','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',2,'ox','auto','9 − 3 − 2 와 9 − 2 − 3 은 답이 같습니다.',ARRAY['M1-2-u2-X02']::text[],false,'{"seq":8,"concept":"M1-2-u2-C2","difficulty":2,"kind":"ox","stem":"9 − 3 − 2 와 9 − 2 − 3 은 답이 같습니다.","answer":"O","reason_options":[{"t":"둘 다 9에서 3과 2를 모두 덜어 내니까","correct":true},{"t":"뺄셈은 순서를 바꾸면 언제나 답이 달라지니까","mis":"M1-2-u2-X02"}],"explanation":["9 − 3 − 2 = 4예요.","9 − 2 − 3 도 4예요 — 빼는 두 수가 같기 때문이에요.","하지만 맨 앞의 수를 바꾸면 답이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#9','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',2,'match','auto','식과 답을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u2-C2","difficulty":2,"kind":"match","stem":"식과 답을 알맞게 이어 보세요.","pairs":[{"l":"9 − 1 − 3","r":"5"},{"l":"8 − 2 − 2","r":"4"},{"l":"7 − 3 − 1","r":"3"}],"explanation":["앞의 두 수를 먼저 계산해요.","9 − 1 = 8, 8 − 3 = 5예요.","식마다 앞에서부터 차례로 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_basic#10','math',1,2,'u2','L03','g1_2_math_u2_L03_basic','lesson_basic','M1-2-u2-C2',3,'error','auto','하늘이가 9 − 4 − 2 를 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#1','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',2,'sa','auto','9 − 3 − 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C2","difficulty":2,"kind":"sa","stem":"9 − 3 − 3 은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9 − 3 = 6이에요.","6 − 3 = 3이에요.","같은 수를 두 번 빼도 한 번씩 차례로 계산해요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#2','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',2,'mc','auto','색종이 8장 가운데 3장으로 배를 접고, 2장으로 학을 접었어요. 남은 색종이는 몇 장인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":2,"concept":"M1-2-u2-C2","difficulty":2,"kind":"mc","stem":"색종이 8장 가운데 3장으로 배를 접고, 2장으로 학을 접었어요. 남은 색종이는 몇 장인가요?","options":[{"t":"3장","correct":true},{"t":"5장","mis":"M1-2-u2-X01"},{"t":"6장","mis":"M1-2-u2-X03"}],"explanation":["8 − 3 = 5장이에요.","5 − 2 = 3장이에요.","5는 배만 접은 뒤의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#3','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',3,'mc','auto','9 − 2 − 3 과 답이 같은 식은 무엇인가요?',ARRAY['M1-2-u2-X02','M1-2-u2-X01']::text[],false,'{"seq":3,"concept":"M1-2-u2-C2","difficulty":3,"kind":"mc","stem":"9 − 2 − 3 과 답이 같은 식은 무엇인가요?","options":[{"t":"9 − 3 − 2","correct":true},{"t":"2 − 3 − 9","mis":"M1-2-u2-X02"},{"t":"9 − 2 + 3","mis":"M1-2-u2-X01"}],"explanation":["9 − 2 − 3 = 4예요.","빼는 수 2와 3의 차례만 바꾸면 답은 그대로 4예요.","맨 앞의 수를 바꾸거나 기호를 바꾸면 답이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#4','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',3,'sa','auto','빈칸에 알맞은 수를 숫자로 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#5','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',3,'error','auto','민수가 7 − 2 − 3 을 계산했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#6','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',3,'ox','auto','9 − 4 − 1 = 4 입니다.',ARRAY['M1-2-u2-X02']::text[],true,'{"seq":6,"concept":"M1-2-u2-C2","difficulty":3,"kind":"ox","stem":"9 − 4 − 1 = 4 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 덜어 내니까","correct":true},{"t":"뒤의 두 수를 먼저 계산하면 되니까","mis":"M1-2-u2-X02"}],"explanation":["9 − 4 = 5예요.","5 − 1 = 4예요 — 맞아요.","뺄셈은 앞에서부터 하나씩 덜어 내요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#7','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',3,'mc','auto','연필 9자루 가운데 언니에게 2자루를 주고, 동생에게 3자루를 주었어요. 그런데 언니가 1자루를 돌려주었어요. 지금 가진 연필은 몇 자루인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":7,"concept":"M1-2-u2-C2","difficulty":3,"kind":"mc","stem":"연필 9자루 가운데 언니에게 2자루를 주고, 동생에게 3자루를 주었어요. 그런데 언니가 1자루를 돌려주었어요. 지금 가진 연필은 몇 자루인가요?","options":[{"t":"5자루","correct":true},{"t":"4자루","mis":"M1-2-u2-X01"},{"t":"3자루","mis":"M1-2-u2-X03"}],"explanation":["9 − 2 − 3 = 4자루예요.","돌려받은 1자루를 더하면 5자루예요.","주면 빼고, 받으면 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#8','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',4,'sa','auto','구슬 8개 가운데 2개를 잃어버리고, 3개를 친구에게 주었어요. 남은 구슬은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C2","difficulty":4,"kind":"sa","stem":"구슬 8개 가운데 2개를 잃어버리고, 3개를 친구에게 주었어요. 남은 구슬은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["8 − 2 = 6개예요.","6 − 3 = 3개예요.","없어진 것은 모두 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#9','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',4,'mc','auto','9, 3, 2 세 수로 만든 뺄셈식 가운데 답이 가장 큰 것은 무엇인가요?',ARRAY['M1-2-u2-X02']::text[],false,'{"seq":9,"concept":"M1-2-u2-C2","difficulty":4,"kind":"mc","stem":"9, 3, 2 세 수로 만든 뺄셈식 가운데 답이 가장 큰 것은 무엇인가요?","options":[{"t":"9 − 2 − 3","correct":true},{"t":"3 − 2 − 9","mis":"M1-2-u2-X02"},{"t":"2 − 3 − 9","mis":"M1-2-u2-X02"}],"explanation":["가장 큰 수 9에서 시작해야 많이 남아요.","9 − 2 − 3 = 4로 가장 커요.","뺄셈은 맨 앞의 수가 무엇인지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L03_challenge#10','math',1,2,'u2','L03','g1_2_math_u2_L03_challenge','lesson_challenge','M1-2-u2-C2',4,'essay','teacher','뺄셈은 왜 앞에서부터 계산해야 하는지, 9 − 4 − 2 를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C2","difficulty":4,"kind":"essay","stem":"뺄셈은 왜 앞에서부터 계산해야 하는지, 9 − 4 − 2 를 예로 들어 설명해 보세요.","answer_guide":"「9 − 4 = 5를 먼저 하고 5 − 2 = 3」처럼 앞의 답을 이어 쓴다는 점, 뒤부터 하면 4 − 2 = 2가 되어 답이 달라진다는 점 가운데 하나라도 말하면 통과.","explanation":["9 − 4 = 5를 먼저 해요.","그 5에서 2를 빼면 3이에요.","뒤부터 하면 다른 답이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#1','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',1,'mc','auto','십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],true,'{"seq":1,"concept":"M1-2-u2-C3","difficulty":1,"kind":"mc","stem":"십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":7,"add":0},"options":[{"t":"3","correct":true},{"t":"7","mis":"M1-2-u2-X05"},{"t":"10","mis":"M1-2-u2-X04"}],"explanation":["빈칸을 세어 보세요 — 3칸이 비어 있어요.","7과 3을 더하면 10이에요.","7은 이미 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#2','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',1,'sa','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C3","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":4,"add":0},"answer":["6"],"explanation":["빈칸이 6칸이에요.","4와 6을 더하면 10이에요.","묻는 것은 빈칸의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#3','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',1,'mc','auto','십 배열판에 9개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],true,'{"seq":3,"concept":"M1-2-u2-C3","difficulty":1,"kind":"mc","stem":"십 배열판에 9개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":9,"add":0},"options":[{"t":"1","correct":true},{"t":"9","mis":"M1-2-u2-X05"},{"t":"2","mis":"M1-2-u2-X04"}],"explanation":["빈칸이 딱 한 칸 남았어요.","9와 1을 더하면 10이에요.","9는 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#4','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',1,'sa','auto','6과 더해서 10이 되는 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M1-2-u2-C3","difficulty":1,"kind":"sa","stem":"6과 더해서 10이 되는 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["6에서 10까지는 4만큼 남았어요.","6 + 4 = 10이에요.","손가락 열 개로 확인해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#5','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#6','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',2,'mc','auto','8과 더해서 10이 되는 수는 무엇인가요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],false,'{"seq":6,"concept":"M1-2-u2-C3","difficulty":2,"kind":"mc","stem":"8과 더해서 10이 되는 수는 무엇인가요?","options":[{"t":"2","correct":true},{"t":"8","mis":"M1-2-u2-X05"},{"t":"3","mis":"M1-2-u2-X04"}],"explanation":["8에서 10까지는 2만큼 남았어요.","8 + 2 = 10이에요.","십 배열판의 빈칸을 세어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#7','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',2,'match','auto','10이 되도록 두 수를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u2-C3","difficulty":2,"kind":"match","stem":"10이 되도록 두 수를 알맞게 이어 보세요.","pairs":[{"l":"1","r":"9"},{"l":"2","r":"8"},{"l":"6","r":"4"}],"explanation":["두 수를 더해 10이 되는 짝을 찾아요.","1과 9, 2와 8, 6과 4예요.","십 배열판의 빈칸을 떠올리면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#8','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',2,'sa','auto','5 + 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C3","difficulty":2,"kind":"sa","stem":"5 + 5 는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["5칸을 채우고 5칸을 더 채워요.","십 배열판이 꽉 차서 10이에요.","5와 5도 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#9','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',2,'ox','auto','6과 5를 더하면 10입니다.',ARRAY['M1-2-u2-X11']::text[],false,'{"seq":9,"concept":"M1-2-u2-C3","difficulty":2,"kind":"ox","stem":"6과 5를 더하면 10입니다.","answer":"X","reason_options":[{"t":"6과 5를 더하면 11이라서","correct":true},{"t":"두 수를 더하면 언제나 10이 되니까","mis":"M1-2-u2-X11"}],"explanation":["6 + 5 = 11이에요.","십 배열판은 칸이 열 개뿐이라 하나가 넘쳐요.","6의 짝은 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_basic#10','math',1,2,'u2','L04','g1_2_math_u2_L04_basic','lesson_basic','M1-2-u2-C3',3,'error','auto','지우가 "7과 4를 더하면 10이야"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#1','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',2,'sa','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C3","difficulty":2,"kind":"sa","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":8,"add":0},"answer":["2"],"explanation":["빈칸이 2칸이에요.","8 + 2 = 10이에요.","8은 이미 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#2','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',2,'mc','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X04','M1-2-u2-X05']::text[],true,'{"seq":2,"concept":"M1-2-u2-C3","difficulty":2,"kind":"mc","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":5,"add":0},"options":[{"t":"5","correct":true},{"t":"4","mis":"M1-2-u2-X04"},{"t":"10","mis":"M1-2-u2-X05"}],"explanation":["빈칸이 5칸이에요.","5 + 5 = 10이에요.","채운 칸과 빈칸의 수가 같아요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
