INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#4','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',3,'mc','auto','더해서 10이 되는 두 수의 짝이 아닌 것은 무엇인가요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":4,"concept":"M1-2-u2-C3","difficulty":3,"kind":"mc","stem":"더해서 10이 되는 두 수의 짝이 아닌 것은 무엇인가요?","options":[{"t":"7과 4","correct":true},{"t":"3과 7","mis":"M1-2-u2-X04"},{"t":"9와 1","mis":"M1-2-u2-X04"}],"explanation":["7 + 4 = 11이라 10을 넘어요.","3 + 7 = 10, 9 + 1 = 10이에요.","10이 되는 짝은 넘치지도 모자라지도 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#5','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',3,'sa','auto','달걀판에 달걀을 열 개까지 넣을 수 있어요. 지금 6개가 들어 있어요. 몇 개를 더 넣으면 달걀판이 가득 차나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u2-C3","difficulty":3,"kind":"sa","stem":"달걀판에 달걀을 열 개까지 넣을 수 있어요. 지금 6개가 들어 있어요. 몇 개를 더 넣으면 달걀판이 가득 차나요? 숫자로 쓰세요.","answer":["4"],"explanation":["빈 자리를 세면 4자리예요.","6 + 4 = 10이에요.","가득 찬다는 말은 10이 된다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#6','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',3,'error','auto','하늘이가 십 배열판을 보고 말했어요. "8칸이 차 있으니까 8개 더 놓으면 10이 돼."
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#7','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',3,'ox','auto','9와 더해서 10이 되는 수는 1입니다.',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":7,"concept":"M1-2-u2-C3","difficulty":3,"kind":"ox","stem":"9와 더해서 10이 되는 수는 1입니다.","answer":"O","reason_options":[{"t":"9에서 10까지 1만큼 남으니까","correct":true},{"t":"9의 짝은 언제나 9라서","mis":"M1-2-u2-X04"}],"explanation":["9 + 1 = 10이에요.","십 배열판에 한 칸만 비어 있어요.","짝은 두 수를 더해 10이 되는 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#8','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',4,'mc','auto','수 카드 3, 6, 7 이 있어요. 이 가운데 두 장을 뽑아 더해 10을 만들려면 어떤 두 장을 뽑아야 하나요?',ARRAY['M1-2-u2-X11','M1-2-u2-X04']::text[],false,'{"seq":8,"concept":"M1-2-u2-C3","difficulty":4,"kind":"mc","stem":"수 카드 3, 6, 7 이 있어요. 이 가운데 두 장을 뽑아 더해 10을 만들려면 어떤 두 장을 뽑아야 하나요?","options":[{"t":"3과 7","correct":true},{"t":"6과 7","mis":"M1-2-u2-X11"},{"t":"3과 6","mis":"M1-2-u2-X04"}],"explanation":["3 + 7 = 10이에요.","6 + 7 = 13으로 넘치고, 3 + 6 = 9로 모자라요.","한 수를 정하고 그 짝이 카드에 있는지 찾아보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#9','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',4,'sa','auto','민수는 딱지 10장을 가지려고 해요. 지금 2장이 있고, 형에게 5장을 받았어요. 몇 장이 더 있어야 10장이 되나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u2-C3","difficulty":4,"kind":"sa","stem":"민수는 딱지 10장을 가지려고 해요. 지금 2장이 있고, 형에게 5장을 받았어요. 몇 장이 더 있어야 10장이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["2 + 5 = 7장이에요.","7의 짝은 3이니 3장이 더 있어야 해요.","먼저 지금 몇 장인지부터 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L04_challenge#10','math',1,2,'u2','L04','g1_2_math_u2_L04_challenge','lesson_challenge','M1-2-u2-C3',4,'essay','teacher','십 배열판을 쓰면 10이 되는 짝을 왜 쉽게 찾을 수 있는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C3","difficulty":4,"kind":"essay","stem":"십 배열판을 쓰면 10이 되는 짝을 왜 쉽게 찾을 수 있는지 설명해 보세요.","answer_guide":"「칸이 열 개로 정해져 있어 빈칸만 세면 된다」는 뜻이 드러나면 통과.","explanation":["십 배열판은 칸이 언제나 열 개예요.","채운 칸을 빼면 빈칸이 곧 짝이 되는 수예요.","눈으로 세니 손가락보다 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#1','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',1,'sa','auto','10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C4","difficulty":1,"kind":"sa","stem":"10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_bond","whole":10,"parts":[7,null]},"answer":["3"],"explanation":["10을 둘로 갈랐어요.","7을 뺀 나머지는 3이에요.","가르기와 모으기는 서로 반대예요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#2','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',1,'mc','auto','10을 가르기 했어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M1-2-u2-X06','M1-2-u2-X04']::text[],true,'{"seq":2,"concept":"M1-2-u2-C4","difficulty":1,"kind":"mc","stem":"10을 가르기 했어요. 빈칸에 알맞은 수는 무엇인가요?","asset":{"type":"number_bond","whole":10,"parts":[null,6]},"options":[{"t":"4","correct":true},{"t":"6","mis":"M1-2-u2-X06"},{"t":"10","mis":"M1-2-u2-X04"}],"explanation":["10에서 6을 뺀 나머지가 빈칸이에요.","빈칸은 4예요.","6은 이미 적혀 있는 수예요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#3','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',1,'mc','auto','더해서 10이 되는 식은 무엇인가요?',ARRAY['M1-2-u2-X04','M1-2-u2-X11']::text[],false,'{"seq":3,"concept":"M1-2-u2-C4","difficulty":1,"kind":"mc","stem":"더해서 10이 되는 식은 무엇인가요?","options":[{"t":"2 + 8","correct":true},{"t":"3 + 6","mis":"M1-2-u2-X04"},{"t":"5 + 6","mis":"M1-2-u2-X11"}],"explanation":["2 + 8 = 10이에요.","3 + 6 = 9로 모자라고, 5 + 6 = 11로 넘쳐요.","10이 되는 짝을 차례로 떠올려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#4','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',1,'sa','auto','2 + □ = 10 입니다. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M1-2-u2-C4","difficulty":1,"kind":"sa","stem":"2 + □ = 10 입니다. 빈칸에 알맞은 수를 숫자로 쓰세요.","answer":["8"],"explanation":["2에서 10까지는 8만큼 남았어요.","2 + 8 = 10이에요.","□가 어디 있는지 먼저 짚어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#5','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#6','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',2,'mc','auto','10이 되는 덧셈식이 아닌 것은 무엇인가요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":6,"concept":"M1-2-u2-C4","difficulty":2,"kind":"mc","stem":"10이 되는 덧셈식이 아닌 것은 무엇인가요?","options":[{"t":"4 + 5","correct":true},{"t":"1 + 9","mis":"M1-2-u2-X04"},{"t":"6 + 4","mis":"M1-2-u2-X04"}],"explanation":["4 + 5 = 9로 하나가 모자라요.","1 + 9와 6 + 4는 둘 다 10이에요.","더해 보고 10인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#7','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',2,'sa','auto','두 수를 모으면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-2-u2-C4","difficulty":2,"kind":"sa","stem":"두 수를 모으면 얼마인가요? 숫자로 쓰세요.","asset":{"type":"number_bond","whole":null,"parts":[5,5]},"answer":["10"],"explanation":["5와 5를 모아요.","모으면 10이에요.","모으기는 두 수를 합치는 거예요."],"variant_rule":{"bond":{"whole":[6,10],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#8','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',2,'match','auto','10이 되도록 덧셈식과 알맞은 수를 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C4","difficulty":2,"kind":"match","stem":"10이 되도록 덧셈식과 알맞은 수를 이어 보세요.","pairs":[{"l":"7 + □","r":"3"},{"l":"2 + □","r":"8"},{"l":"5 + □","r":"5"}],"explanation":["각 식의 앞 수를 보고 짝을 찾아요.","7의 짝은 3, 2의 짝은 8이에요.","5의 짝은 5로 자기 자신과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#9','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',2,'ox','auto','10이 되는 덧셈식은 5 + 5 한 가지뿐입니다.',ARRAY['M1-2-u2-X10']::text[],false,'{"seq":9,"concept":"M1-2-u2-C4","difficulty":2,"kind":"ox","stem":"10이 되는 덧셈식은 5 + 5 한 가지뿐입니다.","answer":"X","reason_options":[{"t":"1 + 9, 2 + 8처럼 여러 가지가 있어서","correct":true},{"t":"10을 만드는 짝은 하나뿐이라서","mis":"M1-2-u2-X10"}],"explanation":["1 + 9, 2 + 8, 3 + 7, 4 + 6, 5 + 5 모두 10이에요.","앞의 수를 하나씩 늘리면 짝을 다 찾을 수 있어요.","5 + 5는 그 가운데 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_basic#10','math',1,2,'u2','L05','g1_2_math_u2_L05_basic','lesson_basic','M1-2-u2-C4',3,'error','auto','보라가 4 + □ = 10 을 풀고 빈칸에 4라고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#1','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',2,'sa','auto','10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C4","difficulty":2,"kind":"sa","stem":"10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_bond","whole":10,"parts":[2,null]},"answer":["8"],"explanation":["10을 둘로 갈랐어요.","2를 뺀 나머지는 8이에요.","가른 두 수를 다시 모으면 10이에요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#2','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',2,'mc','auto','두 수를 모으면 얼마인가요?',ARRAY['M1-2-u2-X06','M1-2-u2-X11']::text[],true,'{"seq":2,"concept":"M1-2-u2-C4","difficulty":2,"kind":"mc","stem":"두 수를 모으면 얼마인가요?","asset":{"type":"number_bond","whole":null,"parts":[3,7]},"options":[{"t":"10","correct":true},{"t":"7","mis":"M1-2-u2-X06"},{"t":"11","mis":"M1-2-u2-X11"}],"explanation":["3과 7을 모아요.","모으면 10이에요.","7은 한쪽 수일 뿐이에요."],"variant_rule":{"bond":{"whole":[6,10],"ask":"whole"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
