INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#4','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',3,'mc','auto','10이 되는 덧셈식은 모두 몇 가지인가요? (0은 쓰지 않고, 1 + 9와 9 + 1은 다른 식으로 셉니다.)',ARRAY['M1-2-u2-X10']::text[],false,'{"seq":4,"concept":"M1-2-u2-C4","difficulty":3,"kind":"mc","stem":"10이 되는 덧셈식은 모두 몇 가지인가요? (0은 쓰지 않고, 1 + 9와 9 + 1은 다른 식으로 셉니다.)","options":[{"t":"9가지","correct":true},{"t":"5가지","mis":"M1-2-u2-X10"},{"t":"1가지","mis":"M1-2-u2-X10"}],"explanation":["앞의 수가 1부터 9까지 아홉 가지예요.","앞의 수마다 짝이 하나씩 있어 9가지예요.","1 + 9부터 9 + 1까지 차례로 적어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#5','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',3,'sa','auto','지우는 사탕 10개를 두 접시에 나누어 담았어요. 한 접시에 7개를 담았다면 다른 접시에는 몇 개를 담았나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u2-C4","difficulty":3,"kind":"sa","stem":"지우는 사탕 10개를 두 접시에 나누어 담았어요. 한 접시에 7개를 담았다면 다른 접시에는 몇 개를 담았나요? 숫자로 쓰세요.","answer":["3"],"explanation":["10을 둘로 가르는 문제예요.","7의 짝은 3이에요.","두 접시의 사탕을 모으면 다시 10이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#6','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',3,'error','auto','민수가 "10이 되는 덧셈식은 5 + 5뿐이야"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#7','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',3,'ox','auto','10을 8과 2로 가르면, 8과 2를 다시 모았을 때 10이 됩니다.',ARRAY['M1-2-u2-X06']::text[],false,'{"seq":7,"concept":"M1-2-u2-C4","difficulty":3,"kind":"ox","stem":"10을 8과 2로 가르면, 8과 2를 다시 모았을 때 10이 됩니다.","answer":"O","reason_options":[{"t":"가르기와 모으기는 서로 반대라서","correct":true},{"t":"가른 두 수는 다시 모을 수 없어서","mis":"M1-2-u2-X06"}],"explanation":["10을 8과 2로 갈랐어요.","8 + 2 = 10으로 다시 돌아와요.","가르기와 모으기는 한 쌍이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#8','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',4,'mc','auto','수 카드 2, 4, 6, 8 이 있어요. 두 장을 뽑아 더해 10을 만드는 방법은 몇 가지인가요? (뽑는 차례는 세지 않습니다.)',ARRAY['M1-2-u2-X10','M1-2-u2-X11']::text[],false,'{"seq":8,"concept":"M1-2-u2-C4","difficulty":4,"kind":"mc","stem":"수 카드 2, 4, 6, 8 이 있어요. 두 장을 뽑아 더해 10을 만드는 방법은 몇 가지인가요? (뽑는 차례는 세지 않습니다.)","options":[{"t":"2가지","correct":true},{"t":"1가지","mis":"M1-2-u2-X10"},{"t":"4가지","mis":"M1-2-u2-X11"}],"explanation":["2 + 8 = 10, 4 + 6 = 10이에요.","그래서 2가지예요.","한 장을 정하고 그 짝이 남은 카드에 있는지 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#9','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',4,'sa','auto','□ + △ = 10 입니다. □가 △보다 2만큼 클 때 □는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u2-C4","difficulty":4,"kind":"sa","stem":"□ + △ = 10 입니다. □가 △보다 2만큼 클 때 □는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["두 수를 모으면 10이에요.","6과 4는 차가 2이고 모으면 10이에요.","5와 5부터 하나씩 옮겨 가며 찾아보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L05_challenge#10','math',1,2,'u2','L05','g1_2_math_u2_L05_challenge','lesson_challenge','M1-2-u2-C4',4,'essay','teacher','10이 되는 덧셈식을 빠짐없이 찾는 방법을 자기 말로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C4","difficulty":4,"kind":"essay","stem":"10이 되는 덧셈식을 빠짐없이 찾는 방법을 자기 말로 설명해 보세요.","answer_guide":"「앞의 수를 1부터 차례로 늘리고 그때마다 짝을 적는다」처럼 순서를 정해 찾는다는 뜻이 드러나면 통과.","explanation":["앞의 수를 1부터 차례로 정해요.","그때마다 10이 되는 짝을 하나씩 적어요.","차례를 지키면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#1','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',1,'mc','auto','십 배열판에 10개가 있었어요. 3개를 덜어 냈어요. 남은 것은 몇 개인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],true,'{"seq":1,"concept":"M1-2-u2-C5","difficulty":1,"kind":"mc","stem":"십 배열판에 10개가 있었어요. 3개를 덜어 냈어요. 남은 것은 몇 개인가요?","asset":{"type":"ten_frame","filled":7,"add":0},"options":[{"t":"7","correct":true},{"t":"13","mis":"M1-2-u2-X07"},{"t":"3","mis":"M1-2-u2-X05"}],"explanation":["10칸 가운데 3칸을 덜어 냈어요.","남은 칸은 7칸이에요.","13은 더한 답이에요 — 빼기는 줄어들어요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#2','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',1,'sa','auto','십 배열판을 보세요. 10개에서 6개를 덜어 냈어요. 남은 것은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C5","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 10개에서 6개를 덜어 냈어요. 남은 것은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":4,"add":0},"answer":["4"],"explanation":["10칸에서 6칸을 덜어 냈어요.","남은 칸은 4칸이에요.","남은 칸만 세면 돼요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#3','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',1,'sa','auto','10 − 6 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M1-2-u2-C5","difficulty":1,"kind":"sa","stem":"10 − 6 은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10에서 6을 덜어 내요.","4가 남아요.","6과 4는 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#4','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',1,'mc','auto','10 − 8 은 얼마인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],false,'{"seq":4,"concept":"M1-2-u2-C5","difficulty":1,"kind":"mc","stem":"10 − 8 은 얼마인가요?","options":[{"t":"2","correct":true},{"t":"18","mis":"M1-2-u2-X07"},{"t":"8","mis":"M1-2-u2-X05"}],"explanation":["10에서 8을 덜어 내요.","2가 남아요.","18은 더한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
