INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#6','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',2,'mc','auto','주스 10잔 가운데 5잔을 마셨어요. 남은 주스는 몇 잔인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],false,'{"seq":6,"concept":"M1-2-u2-C5","difficulty":2,"kind":"mc","stem":"주스 10잔 가운데 5잔을 마셨어요. 남은 주스는 몇 잔인가요?","options":[{"t":"5잔","correct":true},{"t":"15잔","mis":"M1-2-u2-X07"},{"t":"10잔","mis":"M1-2-u2-X05"}],"explanation":["10에서 5를 덜어 내요.","5잔이 남아요.","마신 만큼 줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#7','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',2,'match','auto','식과 답을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u2-C5","difficulty":2,"kind":"match","stem":"식과 답을 알맞게 이어 보세요.","pairs":[{"l":"10 − 2","r":"8"},{"l":"10 − 7","r":"3"},{"l":"10 − 9","r":"1"}],"explanation":["10에서 빼는 수만큼 줄어들어요.","10 − 2 = 8이에요.","빼는 수와 답은 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#8','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',2,'sa','auto','10 − 5 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C5","difficulty":2,"kind":"sa","stem":"10 − 5 는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10에서 5를 덜어 내요.","5가 남아요.","5와 5는 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#9','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',2,'ox','auto','10 − 3 = 13 입니다.',ARRAY['M1-2-u2-X07']::text[],false,'{"seq":9,"concept":"M1-2-u2-C5","difficulty":2,"kind":"ox","stem":"10 − 3 = 13 입니다.","answer":"X","reason_options":[{"t":"빼기는 줄어드는 것이라 답은 7이라서","correct":true},{"t":"빼기는 두 수를 붙여 쓰면 되니까","mis":"M1-2-u2-X07"}],"explanation":["10 − 3 = 7이에요.","13은 10과 3을 더한 수예요.","− 기호를 소리 내어 읽어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_basic#10','math',1,2,'u2','L06','g1_2_math_u2_L06_basic','lesson_basic','M1-2-u2-C5',3,'error','auto','하늘이가 10 − 4 를 계산하고 14라고 썼어요.
