INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#2','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',2,'mc','auto','10 − 7 은 얼마인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],false,'{"seq":2,"concept":"M1-2-u2-C5","difficulty":2,"kind":"mc","stem":"10 − 7 은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"17","mis":"M1-2-u2-X07"},{"t":"7","mis":"M1-2-u2-X05"}],"explanation":["10에서 7을 덜어 내요.","3이 남아요.","7과 3은 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
