INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#4','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',3,'mc','auto','10 − 6 과 답이 같은 식은 무엇인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],false,'{"seq":4,"concept":"M1-2-u2-C5","difficulty":3,"kind":"mc","stem":"10 − 6 과 답이 같은 식은 무엇인가요?","options":[{"t":"10 − 4 − 2","correct":true},{"t":"10 + 6","mis":"M1-2-u2-X07"},{"t":"6 − 10","mis":"M1-2-u2-X05"}],"explanation":["10 − 6 = 4예요.","10 − 4 − 2 도 앞에서부터 계산하면 4예요.","빼는 수를 나누어 두 번 빼도 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#5','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',3,'sa','auto','풍선 10개 가운데 3개가 터지고, 2개를 친구에게 주었어요. 남은 풍선은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u2-C5","difficulty":3,"kind":"sa","stem":"풍선 10개 가운데 3개가 터지고, 2개를 친구에게 주었어요. 남은 풍선은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10 − 3 = 7개예요.","7 − 2 = 5개예요.","없어진 것은 모두 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#6','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',3,'error','auto','민수가 10 − 8 을 계산했어요. "8에서 10은 못 빼니까 8 빼기 10을 거꾸로 해서 2!"
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#7','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',3,'ox','auto','10에서 어떤 수를 뺀 답과 그 어떤 수를 더하면 10이 됩니다.',ARRAY['M1-2-u2-X07']::text[],false,'{"seq":7,"concept":"M1-2-u2-C5","difficulty":3,"kind":"ox","stem":"10에서 어떤 수를 뺀 답과 그 어떤 수를 더하면 10이 됩니다.","answer":"O","reason_options":[{"t":"빼는 수와 남은 수는 10이 되는 짝이라서","correct":true},{"t":"빼기와 더하기는 서로 관계가 없어서","mis":"M1-2-u2-X07"}],"explanation":["10 − 3 = 7이고, 7 + 3 = 10이에요.","빼는 수와 남은 수는 언제나 10이 되는 짝이에요.","가르기와 모으기로도 설명할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#8','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',4,'sa','auto','10 − □ = □ 입니다. 두 빈칸에 같은 수가 들어간다면 그 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C5","difficulty":4,"kind":"sa","stem":"10 − □ = □ 입니다. 두 빈칸에 같은 수가 들어간다면 그 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["빼는 수와 남은 수가 같아야 해요.","5 + 5 = 10이니 5예요.","10을 똑같이 둘로 가른 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#9','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',4,'mc','auto','10에서 어떤 수를 뺐더니 6이 남았어요. 그 어떤 수에 2를 더하면 얼마인가요?',ARRAY['M1-2-u2-X06','M1-2-u2-X07']::text[],false,'{"seq":9,"concept":"M1-2-u2-C5","difficulty":4,"kind":"mc","stem":"10에서 어떤 수를 뺐더니 6이 남았어요. 그 어떤 수에 2를 더하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"4","mis":"M1-2-u2-X06"},{"t":"8","mis":"M1-2-u2-X07"}],"explanation":["10 − 4 = 6이니 뺀 수는 4예요.","4 + 2 = 6이에요.","먼저 뺀 수부터 찾아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#10','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',4,'essay','teacher','10 − 7 을 십 배열판으로 어떻게 설명할 수 있는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C5","difficulty":4,"kind":"essay","stem":"10 − 7 을 십 배열판으로 어떻게 설명할 수 있는지 써 보세요.","answer_guide":"「열 칸을 채워 두고 일곱 칸을 지우면 세 칸이 남는다」처럼 배열판의 칸으로 설명하면 통과.","explanation":["열 칸을 모두 채워 놓아요.","일곱 칸을 덜어 내면 세 칸이 남아요.","남은 칸의 수가 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#1','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',1,'mc','auto','7 + 3 + 5 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X01']::text[],true,'{"seq":1,"concept":"M1-2-u2-C6","difficulty":1,"kind":"mc","stem":"7 + 3 + 5 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.","options":[{"t":"15","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"5","mis":"M1-2-u2-X01"}],"explanation":["7과 3을 더하면 10이에요.","10에 남은 5를 더하면 15예요.","10만 답하면 남은 수를 빠뜨린 거예요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#2','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',1,'sa','auto','6 + 4 + 2 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C6","difficulty":1,"kind":"sa","stem":"6 + 4 + 2 는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["6과 4를 더하면 10이에요.","10에 2를 더하면 12예요.","10을 만든 뒤 남은 수를 꼭 더해요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#3','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',1,'mc','auto','8 + 2 + 5 는 얼마인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":3,"concept":"M1-2-u2-C6","difficulty":1,"kind":"mc","stem":"8 + 2 + 5 는 얼마인가요?","options":[{"t":"15","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"13","mis":"M1-2-u2-X03"}],"explanation":["8과 2를 더하면 10이에요.","10에 5를 더하면 15예요.","10에서 멈추면 안 돼요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#4','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',1,'sa','auto','9 + 1 + 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u2-C6","difficulty":1,"kind":"sa","stem":"9 + 1 + 3 은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["9와 1을 더하면 10이에요.","10에 3을 더하면 13이에요.","10이 되는 짝을 먼저 찾아요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
