INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#6','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',2,'mc','auto','바구니에 사과가 5개 있었어요. 언니가 5개를 넣고, 형이 4개를 더 넣었어요. 사과는 모두 몇 개인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X01']::text[],false,'{"seq":6,"concept":"M1-2-u2-C6","difficulty":2,"kind":"mc","stem":"바구니에 사과가 5개 있었어요. 언니가 5개를 넣고, 형이 4개를 더 넣었어요. 사과는 모두 몇 개인가요?","options":[{"t":"14개","correct":true},{"t":"10개","mis":"M1-2-u2-X08"},{"t":"9개","mis":"M1-2-u2-X01"}],"explanation":["5와 5를 더하면 10개예요.","10개에 4개를 더하면 14개예요.","10에서 멈추면 형이 넣은 것을 빠뜨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#7','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',2,'sa','auto','3 + 7 + 6 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-2-u2-C6","difficulty":2,"kind":"sa","stem":"3 + 7 + 6 은 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["3과 7을 더하면 10이에요.","10에 6을 더하면 16이에요.","10을 만들면 계산이 쉬워져요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#8','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',2,'ox','auto','2 + 8 + 4 = 10 입니다.',ARRAY['M1-2-u2-X08']::text[],false,'{"seq":8,"concept":"M1-2-u2-C6","difficulty":2,"kind":"ox","stem":"2 + 8 + 4 = 10 입니다.","answer":"X","reason_options":[{"t":"10을 만든 뒤 남은 4를 더해야 하니까","correct":true},{"t":"10을 만들면 그것이 답이니까","mis":"M1-2-u2-X08"}],"explanation":["2와 8을 더하면 10이에요.","남은 4를 더해 14가 되어야 해요.","10은 가는 길이지 답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_basic#9','math',1,2,'u2','L07','g1_2_math_u2_L07_basic','lesson_basic','M1-2-u2-C6',2,'match','auto','식과 답을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u2-C6","difficulty":2,"kind":"match","stem":"식과 답을 알맞게 이어 보세요.","pairs":[{"l":"1 + 9 + 2","r":"12"},{"l":"4 + 6 + 5","r":"15"},{"l":"7 + 3 + 8","r":"18"}],"explanation":["앞의 두 수로 10을 먼저 만들어요.","1 + 9 = 10, 10 + 2 = 12예요.","남은 수를 더하는 것을 잊지 마세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
