INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#4','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',3,'mc','auto','2 + 8 + 6 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":4,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"2 + 8 + 6 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?","options":[{"t":"2와 8","correct":true},{"t":"8과 6","mis":"M1-2-u2-X04"},{"t":"2와 6","mis":"M1-2-u2-X04"}],"explanation":["2와 8을 더하면 10이 돼요.","10에 6을 더해 16이에요.","10이 되는 짝을 먼저 찾는 것이 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#5','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',3,'sa','auto','딱지를 어제 8장, 오늘 아침에 2장, 오늘 저녁에 6장 모았어요. 모두 몇 장인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u2-C6","difficulty":3,"kind":"sa","stem":"딱지를 어제 8장, 오늘 아침에 2장, 오늘 저녁에 6장 모았어요. 모두 몇 장인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["8과 2를 더하면 10장이에요.","10장에 6장을 더하면 16장이에요.","10을 만들면 셈이 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#6','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',3,'error','auto','하늘이가 7 + 3 + 9 를 계산했어요. "7과 3으로 10, 그러니까 답은 10 그대로!"
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#7','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',3,'ox','auto','6 + 4 + 7 = 17 입니다.',ARRAY['M1-2-u2-X08']::text[],false,'{"seq":7,"concept":"M1-2-u2-C6","difficulty":3,"kind":"ox","stem":"6 + 4 + 7 = 17 입니다.","answer":"O","reason_options":[{"t":"6과 4로 10을 만들고 남은 7을 더했으니까","correct":true},{"t":"10을 만들면 그것이 답이니까","mis":"M1-2-u2-X08"}],"explanation":["6 + 4 = 10이에요.","10 + 7 = 17이에요 — 맞아요.","10을 만든 뒤 남은 수를 더한 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#8','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',4,'sa','auto','□ + 6 + 5 = 15 입니다. □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C6","difficulty":4,"kind":"sa","stem":"□ + 6 + 5 = 15 입니다. □에 알맞은 수를 숫자로 쓰세요.","answer":["4"],"explanation":["6과 짝을 이뤄 10을 만드는 수는 4예요.","10 + 5 = 15로 맞아요.","남은 수 5를 빼고 생각해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#9','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',4,'mc','auto','수 카드 3, 7, 8 을 모두 한 번씩 써서 더했어요. 답은 얼마인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X01']::text[],false,'{"seq":9,"concept":"M1-2-u2-C6","difficulty":4,"kind":"mc","stem":"수 카드 3, 7, 8 을 모두 한 번씩 써서 더했어요. 답은 얼마인가요?","options":[{"t":"18","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"15","mis":"M1-2-u2-X01"}],"explanation":["3과 7로 10을 만들어요.","10에 8을 더하면 18이에요.","순서를 바꿔도 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#10','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',4,'essay','teacher','세 수를 더할 때 10을 먼저 만들면 왜 편한지, 8 + 2 + 6 을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C6","difficulty":4,"kind":"essay","stem":"세 수를 더할 때 10을 먼저 만들면 왜 편한지, 8 + 2 + 6 을 예로 들어 설명해 보세요.","answer_guide":"「8 + 2로 10을 만들면 10 + 6은 십몇으로 바로 읽힌다」처럼 10이 계산을 쉽게 해 준다는 뜻이 드러나면 통과.","explanation":["8과 2를 더하면 10이에요.","10 + 6은 16으로 바로 읽을 수 있어요.","10을 만들면 셈이 짧아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_basic#1','math',1,2,'u2','L08','g1_2_math_u2_L08_basic','lesson_basic','M1-2-u2-C7',1,'mc','auto','5 + 7 + 3 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":1,"concept":"M1-2-u2-C7","difficulty":1,"kind":"mc","stem":"5 + 7 + 3 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.","options":[{"t":"15","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"12","mis":"M1-2-u2-X03"}],"explanation":["뒤의 두 수 7과 3으로 10을 만들어요.","10에 5를 더하면 15예요.","10은 앞에서도 뒤에서도 만들 수 있어요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
