INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_basic#9','math',1,2,'u2','L08','g1_2_math_u2_L08_basic','lesson_basic','M1-2-u2-C7',2,'match','auto','식과 10을 만드는 두 수를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u2-C7","difficulty":2,"kind":"match","stem":"식과 10을 만드는 두 수를 알맞게 이어 보세요.","pairs":[{"l":"3 + 5 + 5","r":"5와 5"},{"l":"2 + 8 + 4","r":"2와 8"},{"l":"7 + 6 + 4","r":"6과 4"}],"explanation":["더해서 10이 되는 두 수를 찾아요.","3 + 5 + 5 에서는 5와 5예요.","짝은 앞에도, 뒤에도 있을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_basic#10','math',1,2,'u2','L08','g1_2_math_u2_L08_basic','lesson_basic','M1-2-u2-C7',3,'error','auto','민수가 9 − 4 + 6 을 계산하면서 "4와 6으로 10을 만들자!"라고 했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#1','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',2,'sa','auto','4 + 3 + 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C7","difficulty":2,"kind":"sa","stem":"4 + 3 + 7 은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["뒤의 두 수 3과 7로 10을 만들어요.","10에 4를 더하면 14예요.","짝이 뒤에 있으면 뒤에서 묶어요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#2','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',2,'mc','auto','9 + 8 + 2 는 얼마인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":2,"concept":"M1-2-u2-C7","difficulty":2,"kind":"mc","stem":"9 + 8 + 2 는 얼마인가요?","options":[{"t":"19","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"17","mis":"M1-2-u2-X03"}],"explanation":["뒤의 두 수 8과 2로 10을 만들어요.","10에 9를 더하면 19예요.","10에서 멈추면 안 돼요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#3','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',3,'mc','auto','5 + 2 + 8 을 가장 쉽게 계산하는 방법은 무엇인가요?',ARRAY['M1-2-u2-X04','M1-2-u2-X01']::text[],false,'{"seq":3,"concept":"M1-2-u2-C7","difficulty":3,"kind":"mc","stem":"5 + 2 + 8 을 가장 쉽게 계산하는 방법은 무엇인가요?","options":[{"t":"2와 8로 10을 만들고 5를 더한다","correct":true},{"t":"5와 2를 먼저 더한다","mis":"M1-2-u2-X04"},{"t":"세 수를 한꺼번에 센다","mis":"M1-2-u2-X01"}],"explanation":["2 + 8 = 10이에요.","10 + 5 = 15로 바로 읽을 수 있어요.","10이 되는 짝을 먼저 찾는 것이 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#4','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',3,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#5','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',3,'sa','auto','연필을 필통에 3자루, 책상에 8자루, 서랍에 2자루 두었어요. 연필은 모두 몇 자루인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u2-C7","difficulty":3,"kind":"sa","stem":"연필을 필통에 3자루, 책상에 8자루, 서랍에 2자루 두었어요. 연필은 모두 몇 자루인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["뒤의 두 수 8과 2로 10자루를 만들어요.","10자루에 3자루를 더하면 13자루예요.","10을 만들면 셈이 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#6','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',3,'error','auto','보라가 7 + 5 + 5 를 계산하고 "10!"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#7','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',3,'ox','auto','더하기만 있는 세 수의 식에서는 어느 두 수를 먼저 더해도 답이 같습니다.',ARRAY['M1-2-u2-X09']::text[],false,'{"seq":7,"concept":"M1-2-u2-C7","difficulty":3,"kind":"ox","stem":"더하기만 있는 세 수의 식에서는 어느 두 수를 먼저 더해도 답이 같습니다.","answer":"O","reason_options":[{"t":"더하기는 묶는 차례를 바꿔도 답이 그대로라서","correct":true},{"t":"언제나 앞의 두 수만 먼저 더해야 해서","mis":"M1-2-u2-X09"}],"explanation":["2 + 8 + 5 를 앞에서 묶어도, 뒤에서 묶어도 15예요.","그래서 10이 되는 짝을 먼저 묶어도 돼요.","다만 빼기가 섞이면 앞에서부터 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#8','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',4,'sa','auto','수 카드 6, 4, 9 를 모두 한 번씩 써서 더했어요. 답은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u2-C7","difficulty":4,"kind":"sa","stem":"수 카드 6, 4, 9 를 모두 한 번씩 써서 더했어요. 답은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["6과 4로 10을 만들어요.","10에 9를 더하면 19예요.","어느 두 수를 먼저 묶어도 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#9','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',4,'mc','auto','1 + □ + 5 = 15 가 되도록 □에 알맞은 수를 고르세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X06']::text[],false,'{"seq":9,"concept":"M1-2-u2-C7","difficulty":4,"kind":"mc","stem":"1 + □ + 5 = 15 가 되도록 □에 알맞은 수를 고르세요.","options":[{"t":"9","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"5","mis":"M1-2-u2-X06"}],"explanation":["1과 짝을 이뤄 10을 만드는 수는 9예요.","10 + 5 = 15로 맞아요.","짝은 떨어져 있어도 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L08_challenge#10','math',1,2,'u2','L08','g1_2_math_u2_L08_challenge','lesson_challenge','M1-2-u2-C7',4,'essay','teacher','10을 만들 두 수가 앞에 있을 때와 뒤에 있을 때, 계산하는 방법이 어떻게 같고 어떻게 다른지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u2-C7","difficulty":4,"kind":"essay","stem":"10을 만들 두 수가 앞에 있을 때와 뒤에 있을 때, 계산하는 방법이 어떻게 같고 어떻게 다른지 설명해 보세요.","answer_guide":"「어느 쪽이든 10이 되는 짝을 먼저 묶고 남은 수를 더한다」는 공통점이 드러나면 통과. 「더하기만 있을 때만 그렇게 할 수 있다」까지 쓰면 아주 좋음.","explanation":["어느 쪽이든 10이 되는 짝을 먼저 묶어요.","그 다음 남은 수를 더하는 것도 같아요.","다만 빼기가 섞인 식은 앞에서부터 계산해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#1','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C1',1,'mc','auto','그림을 보세요. 병아리는 모두 몇 마리인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],true,'{"seq":1,"concept":"M1-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 병아리는 모두 몇 마리인가요?","asset":{"type":"group_row","groups":[{"item":"🐤","n":2},{"item":"🐤","n":3},{"item":"🐤","n":1}],"op":"+"},"options":[{"t":"6","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"7","mis":"M1-2-u2-X03"}],"explanation":["앞의 두 무리를 먼저 세요 — 2 + 3 = 5.","거기에 1마리를 더하면 6마리예요.","세 무리를 한꺼번에 보지 말고 두 무리씩 세요."],"variant_rule":{"groups":{"items":[["🐤","🐤","🐤"],["🍎","🍎","🍎"],["⚽","⚽","⚽"],["🍪","🍪","🍪"]],"n":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#2','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C1',1,'sa','auto','4 + 2 + 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C1","difficulty":1,"kind":"sa","stem":"4 + 2 + 3 은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["앞에서부터 계산해요 — 4 + 2 = 6.","6 + 3 = 9예요.","두 수씩 두 번 계산하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#3','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C1',2,'mc','auto','버스에 2명이 타고 있었어요. 정류장에서 3명이 타고, 다음 정류장에서 1명이 더 탔어요. 버스에 탄 사람은 모두 몇 명인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":3,"concept":"M1-2-u2-C1","difficulty":2,"kind":"mc","stem":"버스에 2명이 타고 있었어요. 정류장에서 3명이 타고, 다음 정류장에서 1명이 더 탔어요. 버스에 탄 사람은 모두 몇 명인가요?","options":[{"t":"6명","correct":true},{"t":"5명","mis":"M1-2-u2-X01"},{"t":"3명","mis":"M1-2-u2-X03"}],"explanation":["2 + 3 = 5예요.","거기에 1을 더하면 6이에요.","5는 마지막을 빠뜨린 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#4','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C1',3,'error','auto','민수가 3 + 2 + 4 를 계산하고 "5!"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#5','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C2',1,'mc','auto','그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":5,"concept":"M1-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?","asset":{"type":"group_row","groups":[{"item":"🍪","n":7},{"item":"🍪","n":3},{"item":"🍪","n":2}],"op":"-"},"options":[{"t":"2","correct":true},{"t":"4","mis":"M1-2-u2-X01"},{"t":"3","mis":"M1-2-u2-X03"}],"explanation":["처음 7개에서 3개를 덜면 4개예요.","4개에서 2개를 더 덜면 2개가 남아요.","4는 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#6','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C2',1,'sa','auto','9 − 2 − 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u2-C2","difficulty":1,"kind":"sa","stem":"9 − 2 − 4 는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9 − 2 = 7이에요.","7 − 4 = 3이에요.","뺄셈도 앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#7','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C2',2,'ox','auto','8 − 3 − 2 = 3 입니다.',ARRAY['M1-2-u2-X02']::text[],true,'{"seq":7,"concept":"M1-2-u2-C2","difficulty":2,"kind":"ox","stem":"8 − 3 − 2 = 3 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 덜어 내니까","correct":true},{"t":"뒤의 두 수를 먼저 계산하면 되니까","mis":"M1-2-u2-X02"}],"explanation":["8 − 3 = 5예요.","5 − 2 = 3 — 맞아요.","뺄셈은 앞에서부터 하나씩 덜어 내요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#8','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C2',3,'mc','auto','사탕 9개가 있었어요. 지우가 3개를 먹고, 하늘이가 2개를 먹었어요. 남은 사탕은 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":8,"concept":"M1-2-u2-C2","difficulty":3,"kind":"mc","stem":"사탕 9개가 있었어요. 지우가 3개를 먹고, 하늘이가 2개를 먹었어요. 남은 사탕은 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M1-2-u2-X01"},{"t":"7개","mis":"M1-2-u2-X03"}],"explanation":["9 − 3 = 6이에요.","6 − 2 = 4예요.","6은 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#9','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C3',1,'mc','auto','십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],true,'{"seq":9,"concept":"M1-2-u2-C3","difficulty":1,"kind":"mc","stem":"십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":7,"add":0},"options":[{"t":"3","correct":true},{"t":"7","mis":"M1-2-u2-X05"},{"t":"10","mis":"M1-2-u2-X04"}],"explanation":["빈칸을 세어 보세요 — 3칸이 비어 있어요.","7과 3을 더하면 10이에요.","7은 이미 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#10','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C3',1,'sa','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u2-C3","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":4,"add":0},"answer":["6"],"explanation":["빈칸이 6칸이에요.","4 + 6 = 10이에요.","묻는 것은 빈칸의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#11','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C3',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#12','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C3',2,'match','auto','10이 되도록 두 수를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"M1-2-u2-C3","difficulty":2,"kind":"match","stem":"10이 되도록 두 수를 알맞게 이어 보세요.","pairs":[{"l":"1","r":"9"},{"l":"2","r":"8"},{"l":"6","r":"4"}],"explanation":["두 수를 더해 10이 되는 짝을 찾아요.","1과 9, 2와 8이 짝이에요.","십 배열판의 빈칸을 떠올리면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#13','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C4',2,'sa','auto','10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u2-C4","difficulty":2,"kind":"sa","stem":"10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_bond","whole":10,"parts":[7,null]},"answer":["3"],"explanation":["10을 둘로 갈랐어요.","7을 뺀 나머지는 3이에요.","가르기와 모으기는 서로 반대예요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#14','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C4',2,'mc','auto','더해서 10이 되는 식은 무엇인가요?',ARRAY['M1-2-u2-X04','M1-2-u2-X11']::text[],false,'{"seq":14,"concept":"M1-2-u2-C4","difficulty":2,"kind":"mc","stem":"더해서 10이 되는 식은 무엇인가요?","options":[{"t":"2 + 8","correct":true},{"t":"3 + 6","mis":"M1-2-u2-X04"},{"t":"5 + 6","mis":"M1-2-u2-X11"}],"explanation":["2 + 8 = 10이에요.","3 + 6 = 9, 5 + 6 = 11로 10이 아니에요.","10이 되는 짝을 차례로 떠올려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#15','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C4',3,'error','auto','보라가 4 + □ = 10 을 풀고 빈칸에 4라고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#16','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C5',1,'mc','auto','십 배열판에 10개가 있었어요. 3개를 덜어 냈어요. 남은 것은 몇 개인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],true,'{"seq":16,"concept":"M1-2-u2-C5","difficulty":1,"kind":"mc","stem":"십 배열판에 10개가 있었어요. 3개를 덜어 냈어요. 남은 것은 몇 개인가요?","asset":{"type":"ten_frame","filled":7,"add":0},"options":[{"t":"7","correct":true},{"t":"13","mis":"M1-2-u2-X07"},{"t":"3","mis":"M1-2-u2-X05"}],"explanation":["10칸 가운데 3칸을 덜어 냈어요.","남은 칸은 7칸이에요.","빼기는 줄어드는 계산이에요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#17','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C5',1,'sa','auto','10 − 6 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M1-2-u2-C5","difficulty":1,"kind":"sa","stem":"10 − 6 은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["10에서 6을 덜어 내요.","4가 남아요.","6과 4는 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
