INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#19','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C5',3,'ox','auto','10 − 3 = 13 입니다.',ARRAY['M1-2-u2-X07']::text[],false,'{"seq":19,"concept":"M1-2-u2-C5","difficulty":3,"kind":"ox","stem":"10 − 3 = 13 입니다.","answer":"X","reason_options":[{"t":"빼기는 줄어드는 것이라 답은 7라서","correct":true},{"t":"빼기는 두 수를 붙여 쓰면 되니까","mis":"M1-2-u2-X07"}],"explanation":["10 − 3 = 7이에요.","13은 10과 3을 더한 수예요.","− 기호를 소리 내어 읽어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#20','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C6',2,'sa','auto','7 + 3 + 5 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u2-C6","difficulty":2,"kind":"sa","stem":"7 + 3 + 5 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.","answer":["15"],"explanation":["7과 3을 더하면 10이에요.","10에 남은 5를 더하면 15예요.","10을 만든 뒤 남은 수를 꼭 더해요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#21','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C6',3,'mc','auto','바구니에 사과가 5개 있었어요. 언니가 5개를 넣고, 형이 4개를 더 넣었어요. 사과는 모두 몇 개인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],false,'{"seq":21,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"바구니에 사과가 5개 있었어요. 언니가 5개를 넣고, 형이 4개를 더 넣었어요. 사과는 모두 몇 개인가요?","options":[{"t":"14개","correct":true},{"t":"10개","mis":"M1-2-u2-X08"},{"t":"13개","mis":"M1-2-u2-X03"}],"explanation":["5와 5를 더하면 10개가 돼요.","10개에 4개를 더하면 14개예요.","10에서 멈추면 마지막을 빠뜨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#22','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C6',3,'mc','auto','2 + 8 + 6 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":22,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"2 + 8 + 6 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?","options":[{"t":"2와 8","correct":true},{"t":"8과 6","mis":"M1-2-u2-X04"},{"t":"2와 6","mis":"M1-2-u2-X04"}],"explanation":["2 + 8 = 10이 돼요.","10에 6을 더해 16이에요.","10이 되는 짝을 먼저 찾는 것이 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#23','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C7',4,'mc','auto','5 + 7 + 3 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":23,"concept":"M1-2-u2-C7","difficulty":4,"kind":"mc","stem":"5 + 7 + 3 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.","options":[{"t":"15","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"12","mis":"M1-2-u2-X03"}],"explanation":["뒤의 두 수 7과 3으로 10을 만들어요.","10에 5를 더하면 15예요.","10은 앞에서도 뒤에서도 만들 수 있어요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#24','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C7',4,'sa','auto','7 + 2 + □ = 17 입니다. □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M1-2-u2-C7","difficulty":4,"kind":"sa","stem":"7 + 2 + □ = 17 입니다. □에 알맞은 수를 숫자로 쓰세요.","answer":["8"],"explanation":["2와 짝을 이뤄 10을 만드는 수는 8이에요.","7 + 10 = 17로 맞아요.","짝이 뒤의 두 수일 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_a#25','math',1,2,'u2','review','g1_2_math_u2_review_a','unit_review','M1-2-u2-C7',4,'essay','teacher','세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u2-C7","difficulty":4,"kind":"essay","stem":"세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.","answer_guide":"「10이 되는 두 수를 먼저 묶고 남은 수를 더하면 십몇으로 바로 읽힌다」는 뜻이 드러나면 통과. 「더하기만 있을 때만 순서를 바꿀 수 있다」까지 쓰면 아주 좋음.","explanation":["10이 되는 두 수를 먼저 묶어요.","10에 남은 수를 더하면 십몇으로 바로 읽혀요.","빼기가 섞인 식은 앞에서부터 계산해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#1','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C1',1,'mc','auto','그림을 보세요. 사과는 모두 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],true,'{"seq":1,"concept":"M1-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 사과는 모두 몇 개인가요?","asset":{"type":"group_row","groups":[{"item":"🍎","n":3},{"item":"🍎","n":2},{"item":"🍎","n":2}],"op":"+"},"options":[{"t":"7","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"8","mis":"M1-2-u2-X03"}],"explanation":["앞의 두 무리를 먼저 세요 — 3 + 2 = 5.","거기에 2개를 더하면 7개예요.","세 무리를 한꺼번에 보지 말고 두 무리씩 세요."],"variant_rule":{"groups":{"items":[["🐤","🐤","🐤"],["🍎","🍎","🍎"],["⚽","⚽","⚽"],["🍪","🍪","🍪"]],"n":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#2','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C1',1,'sa','auto','2 + 5 + 2 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C1","difficulty":1,"kind":"sa","stem":"2 + 5 + 2 는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["앞에서부터 계산해요 — 2 + 5 = 7.","7 + 2 = 9예요.","두 수씩 두 번 계산하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#3','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C1',2,'mc','auto','놀이터에 아이가 3명 있었어요. 2명이 더 오고, 조금 뒤에 4명이 더 왔어요. 놀이터의 아이는 모두 몇 명인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":3,"concept":"M1-2-u2-C1","difficulty":2,"kind":"mc","stem":"놀이터에 아이가 3명 있었어요. 2명이 더 오고, 조금 뒤에 4명이 더 왔어요. 놀이터의 아이는 모두 몇 명인가요?","options":[{"t":"9명","correct":true},{"t":"5명","mis":"M1-2-u2-X01"},{"t":"7명","mis":"M1-2-u2-X03"}],"explanation":["3 + 2 = 5예요.","거기에 4를 더하면 9예요.","5는 마지막을 빠뜨린 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#4','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C1',3,'error','auto','민수가 4 + 3 + 2 를 계산하고 "7!"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#5','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C2',1,'mc','auto','그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":5,"concept":"M1-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?","asset":{"type":"group_row","groups":[{"item":"⚽","n":8},{"item":"⚽","n":2},{"item":"⚽","n":3}],"op":"-"},"options":[{"t":"3","correct":true},{"t":"6","mis":"M1-2-u2-X01"},{"t":"4","mis":"M1-2-u2-X03"}],"explanation":["처음 8개에서 2개를 덜면 6개예요.","6개에서 3개를 더 덜면 3개가 남아요.","6은 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#6','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C2',1,'sa','auto','8 − 1 − 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u2-C2","difficulty":1,"kind":"sa","stem":"8 − 1 − 4 는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["8 − 1 = 7이에요.","7 − 4 = 3이에요.","뺄셈도 앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#7','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C2',2,'ox','auto','9 − 4 − 2 = 3 입니다.',ARRAY['M1-2-u2-X02']::text[],true,'{"seq":7,"concept":"M1-2-u2-C2","difficulty":2,"kind":"ox","stem":"9 − 4 − 2 = 3 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 덜어 내니까","correct":true},{"t":"뒤의 두 수를 먼저 계산하면 되니까","mis":"M1-2-u2-X02"}],"explanation":["9 − 4 = 5예요.","5 − 2 = 3 — 맞아요.","뺄셈은 앞에서부터 하나씩 덜어 내요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#8','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C2',3,'mc','auto','색종이 8장 가운데 3장으로 배를 접고, 2장으로 학을 접었어요. 남은 색종이는 몇 장인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":8,"concept":"M1-2-u2-C2","difficulty":3,"kind":"mc","stem":"색종이 8장 가운데 3장으로 배를 접고, 2장으로 학을 접었어요. 남은 색종이는 몇 장인가요?","options":[{"t":"3장","correct":true},{"t":"5장","mis":"M1-2-u2-X01"},{"t":"6장","mis":"M1-2-u2-X03"}],"explanation":["8 − 3 = 5예요.","5 − 2 = 3이에요.","5는 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#9','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C3',1,'mc','auto','십 배열판에 6개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],true,'{"seq":9,"concept":"M1-2-u2-C3","difficulty":1,"kind":"mc","stem":"십 배열판에 6개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":6,"add":0},"options":[{"t":"4","correct":true},{"t":"6","mis":"M1-2-u2-X05"},{"t":"10","mis":"M1-2-u2-X04"}],"explanation":["빈칸을 세어 보세요 — 4칸이 비어 있어요.","6과 4를 더하면 10이에요.","6은 이미 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#10','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C3',1,'sa','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u2-C3","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":3,"add":0},"answer":["7"],"explanation":["빈칸이 7칸이에요.","3 + 7 = 10이에요.","묻는 것은 빈칸의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#11','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C3',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#12','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C3',2,'match','auto','10이 되도록 두 수를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"M1-2-u2-C3","difficulty":2,"kind":"match","stem":"10이 되도록 두 수를 알맞게 이어 보세요.","pairs":[{"l":"2","r":"8"},{"l":"5","r":"5"},{"l":"7","r":"3"}],"explanation":["두 수를 더해 10이 되는 짝을 찾아요.","2와 8, 5와 5가 짝이에요.","십 배열판의 빈칸을 떠올리면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#13','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C4',2,'sa','auto','10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u2-C4","difficulty":2,"kind":"sa","stem":"10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_bond","whole":10,"parts":[6,null]},"answer":["4"],"explanation":["10을 둘로 갈랐어요.","6을 뺀 나머지는 4예요.","가르기와 모으기는 서로 반대예요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#14','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C4',2,'mc','auto','더해서 10이 되는 식은 무엇인가요?',ARRAY['M1-2-u2-X04','M1-2-u2-X11']::text[],false,'{"seq":14,"concept":"M1-2-u2-C4","difficulty":2,"kind":"mc","stem":"더해서 10이 되는 식은 무엇인가요?","options":[{"t":"3 + 7","correct":true},{"t":"4 + 5","mis":"M1-2-u2-X04"},{"t":"6 + 5","mis":"M1-2-u2-X11"}],"explanation":["3 + 7 = 10이에요.","4 + 5 = 9, 6 + 5 = 11로 10이 아니에요.","10이 되는 짝을 차례로 떠올려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#15','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C4',3,'error','auto','보라가 6 + □ = 10 을 풀고 빈칸에 6라고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#16','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C5',1,'mc','auto','십 배열판에 10개가 있었어요. 4개를 덜어 냈어요. 남은 것은 몇 개인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],true,'{"seq":16,"concept":"M1-2-u2-C5","difficulty":1,"kind":"mc","stem":"십 배열판에 10개가 있었어요. 4개를 덜어 냈어요. 남은 것은 몇 개인가요?","asset":{"type":"ten_frame","filled":6,"add":0},"options":[{"t":"6","correct":true},{"t":"14","mis":"M1-2-u2-X07"},{"t":"4","mis":"M1-2-u2-X05"}],"explanation":["10칸 가운데 4칸을 덜어 냈어요.","남은 칸은 6칸이에요.","빼기는 줄어드는 계산이에요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#17','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C5',1,'sa','auto','10 − 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M1-2-u2-C5","difficulty":1,"kind":"sa","stem":"10 − 7 은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["10에서 7을 덜어 내요.","3이 남아요.","7과 3은 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#18','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C5',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#19','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C5',3,'ox','auto','10 − 5 = 15 입니다.',ARRAY['M1-2-u2-X07']::text[],false,'{"seq":19,"concept":"M1-2-u2-C5","difficulty":3,"kind":"ox","stem":"10 − 5 = 15 입니다.","answer":"X","reason_options":[{"t":"빼기는 줄어드는 것이라 답은 5라서","correct":true},{"t":"빼기는 두 수를 붙여 쓰면 되니까","mis":"M1-2-u2-X07"}],"explanation":["10 − 5 = 5예요.","15는 10과 5를 더한 수예요.","− 기호를 소리 내어 읽어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#20','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C6',2,'sa','auto','6 + 4 + 7 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u2-C6","difficulty":2,"kind":"sa","stem":"6 + 4 + 7 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.","answer":["17"],"explanation":["6과 4를 더하면 10이에요.","10에 남은 7을 더하면 17이에요.","10을 만든 뒤 남은 수를 꼭 더해요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#21','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C6',3,'mc','auto','상자에 구슬이 4개 있었어요. 지우가 6개를 넣고, 하늘이가 5개를 더 넣었어요. 구슬은 모두 몇 개인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],false,'{"seq":21,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"상자에 구슬이 4개 있었어요. 지우가 6개를 넣고, 하늘이가 5개를 더 넣었어요. 구슬은 모두 몇 개인가요?","options":[{"t":"15개","correct":true},{"t":"10개","mis":"M1-2-u2-X08"},{"t":"14개","mis":"M1-2-u2-X03"}],"explanation":["4와 6을 더하면 10개가 돼요.","10개에 5개를 더하면 15개예요.","10에서 멈추면 마지막을 빠뜨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#22','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C6',3,'mc','auto','3 + 7 + 5 를 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":22,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"3 + 7 + 5 를 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?","options":[{"t":"3과 7","correct":true},{"t":"7과 5","mis":"M1-2-u2-X04"},{"t":"3과 5","mis":"M1-2-u2-X04"}],"explanation":["3 + 7 = 10이 돼요.","10에 5를 더해 15예요.","10이 되는 짝을 먼저 찾는 것이 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#23','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C7',4,'mc','auto','4 + 9 + 1 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":23,"concept":"M1-2-u2-C7","difficulty":4,"kind":"mc","stem":"4 + 9 + 1 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.","options":[{"t":"14","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"13","mis":"M1-2-u2-X03"}],"explanation":["뒤의 두 수 9와 1으로 10을 만들어요.","10에 4를 더하면 14예요.","10은 앞에서도 뒤에서도 만들 수 있어요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#24','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C7',4,'sa','auto','6 + 3 + □ = 16 입니다. □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M1-2-u2-C7","difficulty":4,"kind":"sa","stem":"6 + 3 + □ = 16 입니다. □에 알맞은 수를 숫자로 쓰세요.","answer":["7"],"explanation":["3과 짝을 이뤄 10을 만드는 수는 7이에요.","6 + 10 = 16로 맞아요.","짝이 뒤의 두 수일 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_b#25','math',1,2,'u2','review','g1_2_math_u2_review_b','unit_review','M1-2-u2-C7',4,'essay','teacher','세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u2-C7","difficulty":4,"kind":"essay","stem":"세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.","answer_guide":"「10이 되는 두 수를 먼저 묶고 남은 수를 더하면 십몇으로 바로 읽힌다」는 뜻이 드러나면 통과. 「더하기만 있을 때만 순서를 바꿀 수 있다」까지 쓰면 아주 좋음.","explanation":["10이 되는 두 수를 먼저 묶어요.","10에 남은 수를 더하면 십몇으로 바로 읽혀요.","빼기가 섞인 식은 앞에서부터 계산해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#1','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C1',1,'mc','auto','그림을 보세요. 사탕은 모두 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],true,'{"seq":1,"concept":"M1-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 사탕은 모두 몇 개인가요?","asset":{"type":"group_row","groups":[{"item":"🍬","n":1},{"item":"🍬","n":4},{"item":"🍬","n":3}],"op":"+"},"options":[{"t":"8","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"9","mis":"M1-2-u2-X03"}],"explanation":["앞의 두 무리를 먼저 세요 — 1 + 4 = 5.","거기에 3개를 더하면 8개예요.","세 무리를 한꺼번에 보지 말고 두 무리씩 세요."],"variant_rule":{"groups":{"items":[["🐤","🐤","🐤"],["🍎","🍎","🍎"],["⚽","⚽","⚽"],["🍪","🍪","🍪"]],"n":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#2','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C1',1,'sa','auto','3 + 4 + 2 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C1","difficulty":1,"kind":"sa","stem":"3 + 4 + 2 는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["앞에서부터 계산해요 — 3 + 4 = 7.","7 + 2 = 9예요.","두 수씩 두 번 계산하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#3','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C1',2,'mc','auto','접시에 딸기가 1개 있었어요. 엄마가 4개를 놓고, 아빠가 3개를 더 놓았어요. 딸기는 모두 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":3,"concept":"M1-2-u2-C1","difficulty":2,"kind":"mc","stem":"접시에 딸기가 1개 있었어요. 엄마가 4개를 놓고, 아빠가 3개를 더 놓았어요. 딸기는 모두 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"5개","mis":"M1-2-u2-X01"},{"t":"4개","mis":"M1-2-u2-X03"}],"explanation":["1 + 4 = 5예요.","거기에 3을 더하면 8이에요.","5는 마지막을 빠뜨린 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#4','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C1',3,'error','auto','민수가 2 + 4 + 3 을 계산하고 "6!"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#5','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C2',1,'mc','auto','그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":5,"concept":"M1-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?","asset":{"type":"group_row","groups":[{"item":"🎈","n":9},{"item":"🎈","n":4},{"item":"🎈","n":2}],"op":"-"},"options":[{"t":"3","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"4","mis":"M1-2-u2-X03"}],"explanation":["처음 9개에서 4개를 덜면 5개예요.","5개에서 2개를 더 덜면 3개가 남아요.","5는 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#6','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C2',1,'sa','auto','7 − 2 − 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u2-C2","difficulty":1,"kind":"sa","stem":"7 − 2 − 3 은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["7 − 2 = 5예요.","5 − 3 = 2예요.","뺄셈도 앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#7','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C2',2,'ox','auto','9 − 1 − 5 = 3 입니다.',ARRAY['M1-2-u2-X02']::text[],true,'{"seq":7,"concept":"M1-2-u2-C2","difficulty":2,"kind":"ox","stem":"9 − 1 − 5 = 3 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 덜어 내니까","correct":true},{"t":"뒤의 두 수를 먼저 계산하면 되니까","mis":"M1-2-u2-X02"}],"explanation":["9 − 1 = 8이에요.","8 − 5 = 3 — 맞아요.","뺄셈은 앞에서부터 하나씩 덜어 내요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#8','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C2',3,'mc','auto','연필 9자루 가운데 4자루를 언니에게 주고, 2자루를 동생에게 주었어요. 남은 연필은 몇 자루인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":8,"concept":"M1-2-u2-C2","difficulty":3,"kind":"mc","stem":"연필 9자루 가운데 4자루를 언니에게 주고, 2자루를 동생에게 주었어요. 남은 연필은 몇 자루인가요?","options":[{"t":"3자루","correct":true},{"t":"5자루","mis":"M1-2-u2-X01"},{"t":"7자루","mis":"M1-2-u2-X03"}],"explanation":["9 − 4 = 5예요.","5 − 2 = 3이에요.","5는 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#9','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C3',1,'mc','auto','십 배열판에 8개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],true,'{"seq":9,"concept":"M1-2-u2-C3","difficulty":1,"kind":"mc","stem":"십 배열판에 8개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":8,"add":0},"options":[{"t":"2","correct":true},{"t":"8","mis":"M1-2-u2-X05"},{"t":"10","mis":"M1-2-u2-X04"}],"explanation":["빈칸을 세어 보세요 — 2칸이 비어 있어요.","8과 2를 더하면 10이에요.","8은 이미 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#10','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C3',1,'sa','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u2-C3","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":5,"add":0},"answer":["5"],"explanation":["빈칸이 5칸이에요.","5 + 5 = 10이에요.","묻는 것은 빈칸의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#11','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C3',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#12','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C3',2,'match','auto','10이 되도록 두 수를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"M1-2-u2-C3","difficulty":2,"kind":"match","stem":"10이 되도록 두 수를 알맞게 이어 보세요.","pairs":[{"l":"3","r":"7"},{"l":"4","r":"6"},{"l":"9","r":"1"}],"explanation":["두 수를 더해 10이 되는 짝을 찾아요.","3과 7, 4와 6이 짝이에요.","십 배열판의 빈칸을 떠올리면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#13','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C4',2,'sa','auto','10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u2-C4","difficulty":2,"kind":"sa","stem":"10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_bond","whole":10,"parts":[4,null]},"answer":["6"],"explanation":["10을 둘로 갈랐어요.","4를 뺀 나머지는 6이에요.","가르기와 모으기는 서로 반대예요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#14','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C4',2,'mc','auto','더해서 10이 되는 식은 무엇인가요?',ARRAY['M1-2-u2-X04','M1-2-u2-X11']::text[],false,'{"seq":14,"concept":"M1-2-u2-C4","difficulty":2,"kind":"mc","stem":"더해서 10이 되는 식은 무엇인가요?","options":[{"t":"4 + 6","correct":true},{"t":"2 + 6","mis":"M1-2-u2-X04"},{"t":"7 + 6","mis":"M1-2-u2-X11"}],"explanation":["4 + 6 = 10이에요.","2 + 6 = 8, 7 + 6 = 13로 10이 아니에요.","10이 되는 짝을 차례로 떠올려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#15','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C4',3,'error','auto','보라가 3 + □ = 10 을 풀고 빈칸에 3라고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#16','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C5',1,'mc','auto','십 배열판에 10개가 있었어요. 6개를 덜어 냈어요. 남은 것은 몇 개인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],true,'{"seq":16,"concept":"M1-2-u2-C5","difficulty":1,"kind":"mc","stem":"십 배열판에 10개가 있었어요. 6개를 덜어 냈어요. 남은 것은 몇 개인가요?","asset":{"type":"ten_frame","filled":4,"add":0},"options":[{"t":"4","correct":true},{"t":"16","mis":"M1-2-u2-X07"},{"t":"6","mis":"M1-2-u2-X05"}],"explanation":["10칸 가운데 6칸을 덜어 냈어요.","남은 칸은 4칸이에요.","빼기는 줄어드는 계산이에요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#17','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C5',1,'sa','auto','10 − 2 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M1-2-u2-C5","difficulty":1,"kind":"sa","stem":"10 − 2 은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["10에서 2를 덜어 내요.","8이 남아요.","2와 8은 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
