INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#19','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C5',3,'ox','auto','10 − 4 = 14 입니다.',ARRAY['M1-2-u2-X07']::text[],false,'{"seq":19,"concept":"M1-2-u2-C5","difficulty":3,"kind":"ox","stem":"10 − 4 = 14 입니다.","answer":"X","reason_options":[{"t":"빼기는 줄어드는 것이라 답은 6라서","correct":true},{"t":"빼기는 두 수를 붙여 쓰면 되니까","mis":"M1-2-u2-X07"}],"explanation":["10 − 4 = 6이에요.","14는 10과 4를 더한 수예요.","− 기호를 소리 내어 읽어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#20','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C6',2,'sa','auto','8 + 2 + 6 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u2-C6","difficulty":2,"kind":"sa","stem":"8 + 2 + 6 은 얼마인가요? 10을 먼저 만들어 계산해 보세요.","answer":["16"],"explanation":["8과 2를 더하면 10이에요.","10에 남은 6을 더하면 16이에요.","10을 만든 뒤 남은 수를 꼭 더해요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#21','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C6',3,'mc','auto','책꽂이에 책이 3권 있었어요. 형이 7권을 꽂고, 누나가 6권을 더 꽂았어요. 책은 모두 몇 권인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],false,'{"seq":21,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"책꽂이에 책이 3권 있었어요. 형이 7권을 꽂고, 누나가 6권을 더 꽂았어요. 책은 모두 몇 권인가요?","options":[{"t":"16권","correct":true},{"t":"10권","mis":"M1-2-u2-X08"},{"t":"15권","mis":"M1-2-u2-X03"}],"explanation":["3과 7을 더하면 10권이 돼요.","10권에 6권을 더하면 16권이에요.","10에서 멈추면 마지막을 빠뜨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#22','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C6',3,'mc','auto','4 + 6 + 7 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":22,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"4 + 6 + 7 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?","options":[{"t":"4와 6","correct":true},{"t":"6과 7","mis":"M1-2-u2-X04"},{"t":"4와 7","mis":"M1-2-u2-X04"}],"explanation":["4 + 6 = 10이 돼요.","10에 7을 더해 17이에요.","10이 되는 짝을 먼저 찾는 것이 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#23','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C7',4,'mc','auto','6 + 8 + 2 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":23,"concept":"M1-2-u2-C7","difficulty":4,"kind":"mc","stem":"6 + 8 + 2 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.","options":[{"t":"16","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"14","mis":"M1-2-u2-X03"}],"explanation":["뒤의 두 수 8과 2로 10을 만들어요.","10에 6을 더하면 16이에요.","10은 앞에서도 뒤에서도 만들 수 있어요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#24','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C7',4,'sa','auto','5 + 4 + □ = 15 입니다. □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M1-2-u2-C7","difficulty":4,"kind":"sa","stem":"5 + 4 + □ = 15 입니다. □에 알맞은 수를 숫자로 쓰세요.","answer":["6"],"explanation":["4와 짝을 이뤄 10을 만드는 수는 6이에요.","5 + 10 = 15로 맞아요.","짝이 뒤의 두 수일 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_c#25','math',1,2,'u2','review','g1_2_math_u2_review_c','unit_review','M1-2-u2-C7',4,'essay','teacher','세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u2-C7","difficulty":4,"kind":"essay","stem":"세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.","answer_guide":"「10이 되는 두 수를 먼저 묶고 남은 수를 더하면 십몇으로 바로 읽힌다」는 뜻이 드러나면 통과. 「더하기만 있을 때만 순서를 바꿀 수 있다」까지 쓰면 아주 좋음.","explanation":["10이 되는 두 수를 먼저 묶어요.","10에 남은 수를 더하면 십몇으로 바로 읽혀요.","빼기가 섞인 식은 앞에서부터 계산해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#1','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C1',1,'mc','auto','그림을 보세요. 나뭇잎은 모두 몇 장인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],true,'{"seq":1,"concept":"M1-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 나뭇잎은 모두 몇 장인가요?","asset":{"type":"group_row","groups":[{"item":"🍁","n":3},{"item":"🍁","n":3},{"item":"🍁","n":2}],"op":"+"},"options":[{"t":"8","correct":true},{"t":"6","mis":"M1-2-u2-X01"},{"t":"9","mis":"M1-2-u2-X03"}],"explanation":["앞의 두 무리를 먼저 세요 — 3 + 3 = 6.","거기에 2장을 더하면 8장이에요.","세 무리를 한꺼번에 보지 말고 두 무리씩 세요."],"variant_rule":{"groups":{"items":[["🐤","🐤","🐤"],["🍎","🍎","🍎"],["⚽","⚽","⚽"],["🍪","🍪","🍪"]],"n":[1,3]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#2','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C1',1,'sa','auto','1 + 3 + 4 는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u2-C1","difficulty":1,"kind":"sa","stem":"1 + 3 + 4 는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["앞에서부터 계산해요 — 1 + 3 = 4.","4 + 4 = 8이에요.","두 수씩 두 번 계산하면 돼요."],"variant_rule":{"add3":{"op":"add","max":9}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#3','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C1',2,'mc','auto','바구니에 밤이 3개 있었어요. 할머니가 3개를 넣고, 할아버지가 2개를 더 넣었어요. 밤은 모두 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":3,"concept":"M1-2-u2-C1","difficulty":2,"kind":"mc","stem":"바구니에 밤이 3개 있었어요. 할머니가 3개를 넣고, 할아버지가 2개를 더 넣었어요. 밤은 모두 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"6개","mis":"M1-2-u2-X01"},{"t":"5개","mis":"M1-2-u2-X03"}],"explanation":["3 + 3 = 6이에요.","거기에 2를 더하면 8이에요.","6은 마지막을 빠뜨린 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#4','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C1',3,'error','auto','민수가 5 + 2 + 2 를 계산하고 "7!"라고 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#5','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C2',1,'mc','auto','그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":5,"concept":"M1-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 앞에서부터 차례로 덜어 내면 몇 개가 남나요?","asset":{"type":"group_row","groups":[{"item":"🐟","n":8},{"item":"🐟","n":3},{"item":"🐟","n":3}],"op":"-"},"options":[{"t":"2","correct":true},{"t":"5","mis":"M1-2-u2-X01"},{"t":"3","mis":"M1-2-u2-X03"}],"explanation":["처음 8개에서 3개를 덜면 5개예요.","5개에서 3개를 더 덜면 2개가 남아요.","5는 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#6','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C2',1,'sa','auto','9 − 3 − 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u2-C2","difficulty":1,"kind":"sa","stem":"9 − 3 − 3 은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9 − 3 = 6이에요.","6 − 3 = 3이에요.","뺄셈도 앞에서부터 두 수씩 계산해요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#7','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C2',2,'ox','auto','7 − 2 − 3 = 2 입니다.',ARRAY['M1-2-u2-X02']::text[],true,'{"seq":7,"concept":"M1-2-u2-C2","difficulty":2,"kind":"ox","stem":"7 − 2 − 3 = 2 입니다.","answer":"O","reason_options":[{"t":"앞에서부터 두 수씩 차례로 덜어 내니까","correct":true},{"t":"뒤의 두 수를 먼저 계산하면 되니까","mis":"M1-2-u2-X02"}],"explanation":["7 − 2 = 5예요.","5 − 3 = 2 — 맞아요.","뺄셈은 앞에서부터 하나씩 덜어 내요."],"variant_rule":{"add3":{"op":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#8','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C2',3,'mc','auto','구슬 8개 가운데 2개를 잃어버리고, 3개를 친구에게 주었어요. 남은 구슬은 몇 개인가요?',ARRAY['M1-2-u2-X01','M1-2-u2-X03']::text[],false,'{"seq":8,"concept":"M1-2-u2-C2","difficulty":3,"kind":"mc","stem":"구슬 8개 가운데 2개를 잃어버리고, 3개를 친구에게 주었어요. 남은 구슬은 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M1-2-u2-X01"},{"t":"5개","mis":"M1-2-u2-X03"}],"explanation":["8 − 2 = 6이에요.","6 − 3 = 3이에요.","6은 한 번만 덜어 낸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#9','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C3',1,'mc','auto','십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?',ARRAY['M1-2-u2-X05','M1-2-u2-X04']::text[],true,'{"seq":9,"concept":"M1-2-u2-C3","difficulty":1,"kind":"mc","stem":"십 배열판에 7개가 놓여 있어요. 10이 되려면 몇 개 더 놓아야 하나요?","asset":{"type":"ten_frame","filled":7,"add":0},"options":[{"t":"3","correct":true},{"t":"7","mis":"M1-2-u2-X05"},{"t":"10","mis":"M1-2-u2-X04"}],"explanation":["빈칸을 세어 보세요 — 3칸이 비어 있어요.","7과 3을 더하면 10이에요.","7은 이미 놓인 것의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#10','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C3',1,'sa','auto','십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u2-C3","difficulty":1,"kind":"sa","stem":"십 배열판을 보세요. 10이 되려면 몇 개 더 놓아야 하나요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":2,"add":0},"answer":["8"],"explanation":["빈칸이 8칸이에요.","2 + 8 = 10이에요.","묻는 것은 빈칸의 수예요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"rest"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#11','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C3',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#12','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C3',2,'match','auto','10이 되도록 두 수를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":12,"concept":"M1-2-u2-C3","difficulty":2,"kind":"match","stem":"10이 되도록 두 수를 알맞게 이어 보세요.","pairs":[{"l":"4","r":"6"},{"l":"8","r":"2"},{"l":"1","r":"9"}],"explanation":["두 수를 더해 10이 되는 짝을 찾아요.","4와 6, 8과 2가 짝이에요.","십 배열판의 빈칸을 떠올리면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#13','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C4',2,'sa','auto','10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u2-C4","difficulty":2,"kind":"sa","stem":"10을 가르기 했어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_bond","whole":10,"parts":[8,null]},"answer":["2"],"explanation":["10을 둘로 갈랐어요.","8을 뺀 나머지는 2예요.","가르기와 모으기는 서로 반대예요."],"variant_rule":{"bond":{"whole":10,"ask":"part"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#14','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C4',2,'mc','auto','더해서 10이 되는 식은 무엇인가요?',ARRAY['M1-2-u2-X04','M1-2-u2-X11']::text[],false,'{"seq":14,"concept":"M1-2-u2-C4","difficulty":2,"kind":"mc","stem":"더해서 10이 되는 식은 무엇인가요?","options":[{"t":"5 + 5","correct":true},{"t":"3 + 5","mis":"M1-2-u2-X04"},{"t":"8 + 4","mis":"M1-2-u2-X11"}],"explanation":["5 + 5 = 10이에요.","3 + 5 = 8, 8 + 4 = 12로 10이 아니에요.","10이 되는 짝을 차례로 떠올려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#15','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C4',3,'error','auto','보라가 7 + □ = 10 을 풀고 빈칸에 7라고 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#16','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C5',1,'mc','auto','십 배열판에 10개가 있었어요. 8개를 덜어 냈어요. 남은 것은 몇 개인가요?',ARRAY['M1-2-u2-X07','M1-2-u2-X05']::text[],true,'{"seq":16,"concept":"M1-2-u2-C5","difficulty":1,"kind":"mc","stem":"십 배열판에 10개가 있었어요. 8개를 덜어 냈어요. 남은 것은 몇 개인가요?","asset":{"type":"ten_frame","filled":2,"add":0},"options":[{"t":"2","correct":true},{"t":"18","mis":"M1-2-u2-X07"},{"t":"8","mis":"M1-2-u2-X05"}],"explanation":["10칸 가운데 8칸을 덜어 냈어요.","남은 칸은 2칸이에요.","빼기는 줄어드는 계산이에요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#17','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C5',1,'sa','auto','10 − 3 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M1-2-u2-C5","difficulty":1,"kind":"sa","stem":"10 − 3 은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["10에서 3을 덜어 내요.","7이 남아요.","3과 7은 10이 되는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#18','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C5',2,'blank','auto','빈칸에 알맞은 수를 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#19','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C5',3,'ox','auto','10 − 8 = 18 입니다.',ARRAY['M1-2-u2-X07']::text[],false,'{"seq":19,"concept":"M1-2-u2-C5","difficulty":3,"kind":"ox","stem":"10 − 8 = 18 입니다.","answer":"X","reason_options":[{"t":"빼기는 줄어드는 것이라 답은 2라서","correct":true},{"t":"빼기는 두 수를 붙여 쓰면 되니까","mis":"M1-2-u2-X07"}],"explanation":["10 − 8 = 2예요.","18은 10과 8을 더한 수예요.","− 기호를 소리 내어 읽어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#20','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C6',2,'sa','auto','9 + 1 + 4 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.','{}'::text[],true,'{"seq":20,"concept":"M1-2-u2-C6","difficulty":2,"kind":"sa","stem":"9 + 1 + 4 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.","answer":["14"],"explanation":["9와 1을 더하면 10이에요.","10에 남은 4를 더하면 14예요.","10을 만든 뒤 남은 수를 꼭 더해요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#21','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C6',3,'mc','auto','화분에 씨앗을 2개 심었어요. 다음 날 8개를 더 심고, 그 다음 날 3개를 더 심었어요. 씨앗은 모두 몇 개인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],false,'{"seq":21,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"화분에 씨앗을 2개 심었어요. 다음 날 8개를 더 심고, 그 다음 날 3개를 더 심었어요. 씨앗은 모두 몇 개인가요?","options":[{"t":"13개","correct":true},{"t":"10개","mis":"M1-2-u2-X08"},{"t":"12개","mis":"M1-2-u2-X03"}],"explanation":["2와 8을 더하면 10개가 돼요.","10개에 3개를 더하면 13개예요.","10에서 멈추면 마지막을 빠뜨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#22','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C6',3,'mc','auto','4 + 6 + 8 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?',ARRAY['M1-2-u2-X04']::text[],false,'{"seq":22,"concept":"M1-2-u2-C6","difficulty":3,"kind":"mc","stem":"4 + 6 + 8 을 가장 쉽게 계산하려면 어느 두 수를 먼저 더해야 하나요?","options":[{"t":"4와 6","correct":true},{"t":"6과 8","mis":"M1-2-u2-X04"},{"t":"4와 8","mis":"M1-2-u2-X04"}],"explanation":["4 + 6 = 10이 돼요.","10에 8을 더해 18이에요.","10이 되는 짝을 먼저 찾는 것이 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#23','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C7',4,'mc','auto','3 + 6 + 4 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":23,"concept":"M1-2-u2-C7","difficulty":4,"kind":"mc","stem":"3 + 6 + 4 는 얼마인가요? 10을 먼저 만들어 계산해 보세요.","options":[{"t":"13","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"9","mis":"M1-2-u2-X03"}],"explanation":["뒤의 두 수 6과 4로 10을 만들어요.","10에 3을 더하면 13이에요.","10은 앞에서도 뒤에서도 만들 수 있어요."],"variant_rule":{"maketen":{"pos":"back","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#24','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C7',4,'sa','auto','4 + 5 + □ = 14 입니다. □에 알맞은 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M1-2-u2-C7","difficulty":4,"kind":"sa","stem":"4 + 5 + □ = 14 입니다. □에 알맞은 수를 숫자로 쓰세요.","answer":["5"],"explanation":["5와 짝을 이뤄 10을 만드는 수는 5예요.","4 + 10 = 14로 맞아요.","짝이 뒤의 두 수일 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_review_d#25','math',1,2,'u2','review','g1_2_math_u2_review_d','unit_review','M1-2-u2-C7',4,'essay','teacher','세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u2-C7","difficulty":4,"kind":"essay","stem":"세 수를 더할 때 10을 먼저 만들면 왜 편한지, 배운 것을 예로 들어 설명해 보세요.","answer_guide":"「10이 되는 두 수를 먼저 묶고 남은 수를 더하면 십몇으로 바로 읽힌다」는 뜻이 드러나면 통과. 「더하기만 있을 때만 순서를 바꿀 수 있다」까지 쓰면 아주 좋음.","explanation":["10이 되는 두 수를 먼저 묶어요.","10에 남은 수를 더하면 십몇으로 바로 읽혀요.","빼기가 섞인 식은 앞에서부터 계산해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
